            "CREATE TABLE actor_pack_persona_intents (\n    intent_id TEXT PRIMARY KEY\n        CHECK(length(intent_id) = 32\n              AND intent_id = lower(intent_id)\n              AND intent_id NOT GLOB '*[^0-9a-f]*'),\n    persona_id TEXT NOT NULL\n        CHECK(length(persona_id) BETWEEN 1 AND 200\n              AND instr(persona_id, char(0)) = 0),\n    operation TEXT NOT NULL CHECK(operation IN ('create', 'copy', 'update')),\n    state TEXT NOT NULL CHECK(state IN ('prepared', 'committed', 'quarantined')),\n    old_profile_json TEXT CHECK(old_profile_json IS NULL OR length(old_profile_json) <= 2097152),\n    new_profile_json TEXT NOT NULL CHECK(length(new_profile_json) <= 2097152),\n    old_profile_sha256 TEXT\n        CHECK(old_profile_sha256 IS NULL OR (\n              length(old_profile_sha256) = 64\n              AND old_profile_sha256 NOT GLOB '*[^0-9a-f]*')),\n    new_profile_sha256 TEXT NOT NULL\n        CHECK(length(new_profile_sha256) = 64\n              AND new_profile_sha256 NOT GLOB '*[^0-9a-f]*'),\n    old_store_sha256 TEXT NOT NULL\n        CHECK(length(old_store_sha256) = 64\n              AND old_store_sha256 NOT GLOB '*[^0-9a-f]*'),\n    new_store_sha256 TEXT NOT NULL\n        CHECK(length(new_store_sha256) = 64\n              AND new_store_sha256 NOT GLOB '*[^0-9a-f]*'),\n    old_registry_uuid TEXT\n        CHECK(old_registry_uuid IS NULL OR (\n              length(old_registry_uuid) = 36\n              AND old_registry_uuid = lower(old_registry_uuid)\n              AND old_registry_uuid NOT GLOB '*[^0-9a-f-]*'\n              AND length(replace(old_registry_uuid, '-', '')) = 32\n              AND substr(old_registry_uuid, 9, 1) = '-'\n              AND substr(old_registry_uuid, 14, 1) = '-'\n              AND substr(old_registry_uuid, 15, 1) = '4'\n              AND substr(old_registry_uuid, 19, 1) = '-'\n              AND substr(old_registry_uuid, 20, 1) IN ('8', '9', 'a', 'b')\n              AND substr(old_registry_uuid, 24, 1) = '-')),\n    new_registry_uuid TEXT NOT NULL\n        CHECK(length(new_registry_uuid) = 36\n              AND new_registry_uuid = lower(new_registry_uuid)\n              AND new_registry_uuid NOT GLOB '*[^0-9a-f-]*'\n              AND length(replace(new_registry_uuid, '-', '')) = 32\n              AND substr(new_registry_uuid, 9, 1) = '-'\n              AND substr(new_registry_uuid, 14, 1) = '-'\n              AND substr(new_registry_uuid, 15, 1) = '4'\n              AND substr(new_registry_uuid, 19, 1) = '-'\n              AND substr(new_registry_uuid, 20, 1) IN ('8', '9', 'a', 'b')\n              AND substr(new_registry_uuid, 24, 1) = '-'),\n    quarantine_reason TEXT\n        CHECK(quarantine_reason IS NULL OR (\n              length(quarantine_reason) BETWEEN 1 AND 64\n              AND quarantine_reason NOT GLOB '*[^a-z0-9_]*')),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE actor_portable_identities (\n    actor_kind TEXT NOT NULL\n        CHECK(actor_kind IN ('character', 'persona')),\n    local_actor_id TEXT NOT NULL\n        CHECK(length(local_actor_id) BETWEEN 1 AND 200\n              AND instr(local_actor_id, char(0)) = 0),\n    portable_uuid TEXT NOT NULL UNIQUE\n        CHECK(length(portable_uuid) = 36\n              AND portable_uuid = lower(portable_uuid)\n              AND portable_uuid NOT GLOB '*[^0-9a-f-]*'\n              AND length(replace(portable_uuid, '-', '')) = 32\n              AND substr(portable_uuid, 9, 1) = '-'\n              AND substr(portable_uuid, 14, 1) = '-'\n              AND substr(portable_uuid, 15, 1) = '4'\n              AND substr(portable_uuid, 19, 1) = '-'\n              AND substr(portable_uuid, 20, 1) IN ('8', '9', 'a', 'b')\n              AND substr(portable_uuid, 24, 1) = '-'),\n    source_portable_uuid TEXT\n        CHECK(source_portable_uuid IS NULL OR (\n              length(source_portable_uuid) = 36\n              AND source_portable_uuid = lower(source_portable_uuid)\n              AND source_portable_uuid NOT GLOB '*[^0-9a-f-]*'\n              AND length(replace(source_portable_uuid, '-', '')) = 32\n              AND substr(source_portable_uuid, 9, 1) = '-'\n              AND substr(source_portable_uuid, 14, 1) = '-'\n              AND substr(source_portable_uuid, 15, 1) = '4'\n              AND substr(source_portable_uuid, 19, 1) = '-'\n              AND substr(source_portable_uuid, 20, 1) IN ('8', '9', 'a', 'b')\n              AND substr(source_portable_uuid, 24, 1) = '-'\n              AND source_portable_uuid <> portable_uuid)),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),\n    PRIMARY KEY(actor_kind, local_actor_id)\n)",
            "CREATE TABLE agent_lessons_seed_state(\n  profile_id TEXT NOT NULL,\n  dataset_id TEXT NOT NULL,\n  scope_mode TEXT NOT NULL CHECK(scope_mode IN ('local_only', 'synchronized')),\n  state TEXT NOT NULL CHECK(state IN ('unknown', 'not_seeded', 'seeded')),\n  folder_sync_id TEXT,\n  seed_fingerprint TEXT NOT NULL CHECK(\n    length(seed_fingerprint) = 64\n    AND seed_fingerprint = lower(seed_fingerprint)\n    AND seed_fingerprint NOT GLOB '*[^0-9a-f]*'\n  ),\n  PRIMARY KEY(profile_id, dataset_id)\n) WITHOUT ROWID",
            "CREATE TABLE buddy_profiles (\n    id TEXT PRIMARY KEY CHECK(length(id) BETWEEN 1 AND 128),\n    name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 256),\n    status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived','deleted')),\n    source_key TEXT UNIQUE,\n    version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE buddy_visual_bindings (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    buddy_id TEXT NOT NULL REFERENCES buddy_profiles(id),\n    buddy_revision INTEGER NOT NULL CHECK(buddy_revision > 0),\n    pack_id INTEGER NOT NULL REFERENCES persona_visual_packs(id),\n    active_version_id INTEGER NOT NULL,\n    status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived','deleted')),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),\n    FOREIGN KEY(pack_id,active_version_id) REFERENCES persona_visual_pack_versions(pack_id,id)\n)",
            "CREATE TABLE canvas_conversation_hints(\n  conversation_id TEXT PRIMARY KEY NOT NULL\n    REFERENCES conversations(id) ON DELETE CASCADE,\n  last_canvas_id TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n    CHECK(length(updated_at) > 0),\n  FOREIGN KEY(last_canvas_id, conversation_id)\n    REFERENCES canvas_documents(id, conversation_id) ON DELETE CASCADE\n)",
            "CREATE TABLE canvas_documents(\n  id TEXT PRIMARY KEY NOT NULL\n    CHECK(length(id) = 36),\n  conversation_id TEXT NOT NULL\n    REFERENCES conversations(id) ON DELETE CASCADE,\n  created_at TEXT NOT NULL\n    CHECK(length(created_at) > 0),\n  deleted INTEGER NOT NULL DEFAULT 0\n    CHECK(deleted IN (0, 1)),\n  deleted_at TEXT DEFAULT NULL,\n  CHECK(\n    (deleted = 0 AND deleted_at IS NULL)\n    OR (deleted = 1 AND length(deleted_at) > 0)\n  )\n)",
            "CREATE TABLE canvas_revisions(\n  id TEXT PRIMARY KEY NOT NULL\n    CHECK(length(id) = 36),\n  canvas_id TEXT NOT NULL\n    REFERENCES canvas_documents(id) ON DELETE CASCADE,\n  parent_revision_id TEXT DEFAULT NULL,\n  sequence INTEGER NOT NULL\n    CHECK(sequence > 0),\n  title TEXT NOT NULL\n    CHECK(length(title) > 0),\n  runtime_profile TEXT NOT NULL\n    CHECK(\n      length(runtime_profile) BETWEEN 3 AND 64\n      AND runtime_profile = lower(runtime_profile)\n      AND substr(runtime_profile, 1, 1) GLOB '[a-z]'\n      AND runtime_profile NOT GLOB '*[^a-z0-9-]*'\n      AND instr(runtime_profile, '-') > 1\n      AND runtime_profile NOT LIKE '%--%'\n      AND substr(runtime_profile, -1) <> '-'\n    ),\n  html TEXT NOT NULL,\n  content_sha256 TEXT NOT NULL\n    CHECK(\n      length(content_sha256) = 64\n      AND content_sha256 NOT GLOB '*[^0-9a-f]*'\n    ),\n  html_bytes INTEGER NOT NULL\n    CHECK(html_bytes >= 0 AND html_bytes = length(CAST(html AS BLOB))),\n  actor_kind TEXT NOT NULL\n    CHECK(actor_kind IN ('assistant', 'user_rename', 'user_import')),\n  origin_message_id TEXT NOT NULL\n    REFERENCES messages(id) ON DELETE RESTRICT,\n  origin_turn_id TEXT NOT NULL\n    CHECK(length(origin_turn_id) > 0),\n  created_at TEXT NOT NULL\n    CHECK(length(created_at) > 0),\n  deleted_at TEXT DEFAULT NULL,\n  CHECK(\n    typeof(html) = 'text'\n    AND canvas_revision_payload_valid(\n      CAST(html AS BLOB), content_sha256, html_bytes\n    ) = 1\n  ),\n  CHECK(\n    (sequence = 1 AND parent_revision_id IS NULL)\n    OR (sequence > 1 AND parent_revision_id IS NOT NULL)\n  ),\n  FOREIGN KEY(parent_revision_id, canvas_id)\n    REFERENCES canvas_revisions(id, canvas_id)\n)",
            "CREATE TABLE character_cards(\n  id            INTEGER  PRIMARY KEY AUTOINCREMENT,\n  name          TEXT     UNIQUE NOT NULL,\n  description   TEXT,\n  personality   TEXT,\n  scenario      TEXT,\n  system_prompt TEXT,\n  image                     BLOB,\n  post_history_instructions TEXT,\n  first_message             TEXT,\n  message_example           TEXT,\n  creator_notes             TEXT,\n  alternate_greetings       TEXT,\n  tags                      TEXT,\n  creator                   TEXT,\n  character_version         TEXT,\n  extensions                TEXT,\n  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_modified DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted       BOOLEAN  NOT NULL DEFAULT 0,\n  client_id     TEXT     NOT NULL DEFAULT 'unknown',\n  version       INTEGER  NOT NULL DEFAULT 1\n)",
            "CREATE VIRTUAL TABLE character_cards_fts\nUSING fts5(\n  name, description, personality, scenario, system_prompt,\n  content='character_cards',\n  content_rowid='id'\n)",
            "CREATE TABLE 'character_cards_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'character_cards_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'character_cards_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'character_cards_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE VIRTUAL TABLE character_conversation_fts USING fts5(\n  character_label,\n  title,\n  body,\n  content='character_conversation_search_documents',\n  content_rowid='document_id'\n)",
            "CREATE TABLE 'character_conversation_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'character_conversation_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'character_conversation_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'character_conversation_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE character_conversation_search_dirty(\n  conversation_id TEXT PRIMARY KEY NOT NULL,\n  data_authority_id TEXT NOT NULL,\n  source_revision INTEGER NOT NULL CHECK(source_revision >= 0),\n  enqueued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE character_conversation_search_documents(\n  document_id INTEGER PRIMARY KEY AUTOINCREMENT,\n  data_authority_id TEXT NOT NULL,\n  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n  character_id INTEGER NOT NULL REFERENCES character_cards(id) ON DELETE CASCADE,\n  character_label TEXT NOT NULL,\n  title TEXT NOT NULL,\n  body TEXT NOT NULL,\n  eligibility_digest TEXT NOT NULL,\n  validated_eligibility_digest TEXT NOT NULL,\n  source_revision INTEGER NOT NULL CHECK(source_revision >= 0),\n  generation_id TEXT NOT NULL\n    REFERENCES character_conversation_search_generations(generation_id) ON DELETE CASCADE,\n  UNIQUE(data_authority_id, generation_id, conversation_id)\n)",
            "CREATE TABLE character_conversation_search_generations(\n  generation_id TEXT PRIMARY KEY NOT NULL,\n  data_authority_id TEXT NOT NULL,\n  status TEXT NOT NULL CHECK(status IN ('building', 'ready', 'failed')),\n  policy_version INTEGER NOT NULL CHECK(policy_version > 0),\n  source_revision INTEGER NOT NULL CHECK(source_revision >= 0),\n  processed_conversations INTEGER NOT NULL DEFAULT 0 CHECK(processed_conversations >= 0),\n  error_code TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  completed_at TEXT,\n  lease_expires_at TEXT,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE character_conversation_search_revision(\n  singleton_id INTEGER PRIMARY KEY CHECK(singleton_id = 1),\n  data_revision INTEGER NOT NULL CHECK(data_revision >= 0),\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE character_conversation_search_state(\n  singleton_id INTEGER PRIMARY KEY CHECK(singleton_id = 1),\n  data_authority_id TEXT,\n  active_policy_version INTEGER,\n  activated INTEGER NOT NULL DEFAULT 0 CHECK(activated IN (0, 1)),\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE character_expression_images(\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  character_id  INTEGER NOT NULL REFERENCES character_cards(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  state_id      TEXT    NOT NULL,\n  image         BLOB    NOT NULL,\n  mime          TEXT,\n  created_at    TEXT    NOT NULL DEFAULT (STRFTIME('%Y-%m-%dT%H:%M:%fZ','NOW')),\n  updated_at    TEXT    NOT NULL DEFAULT (STRFTIME('%Y-%m-%dT%H:%M:%fZ','NOW')),\n  deleted       INTEGER NOT NULL DEFAULT 0,\n  UNIQUE(character_id, state_id)\n)",
            "CREATE TABLE chat_dictionaries(\n  id              INTEGER  PRIMARY KEY AUTOINCREMENT,\n  name            TEXT     UNIQUE NOT NULL,\n  description     TEXT,\n  file_path       TEXT,\n  content         TEXT,\n  entries_json    TEXT,     -- JSON array of ChatDictionary objects\n  strategy        TEXT     DEFAULT 'sorted_evenly',\n  max_tokens      INTEGER  DEFAULT 1000,\n  enabled         BOOLEAN  NOT NULL DEFAULT 1,\n  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_modified   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted         BOOLEAN  NOT NULL DEFAULT 0,\n  client_id       TEXT     NOT NULL DEFAULT 'unknown',\n  version         INTEGER  NOT NULL DEFAULT 1\n)",
            "CREATE VIRTUAL TABLE chat_dictionaries_fts\nUSING fts5(\n  name, description, content,\n  content='chat_dictionaries',\n  content_rowid='id'\n)",
            "CREATE TABLE 'chat_dictionaries_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'chat_dictionaries_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'chat_dictionaries_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'chat_dictionaries_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE collection_keywords(\n  collection_id INTEGER NOT NULL REFERENCES keyword_collections(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  keyword_id    INTEGER NOT NULL REFERENCES keywords(id)            ON DELETE CASCADE ON UPDATE CASCADE,\n  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY(collection_id,keyword_id)\n)",
            "CREATE TABLE console_auxiliary_attempts(\n  operation_id             TEXT PRIMARY KEY NOT NULL,\n  conversation_id          TEXT NOT NULL\n                               REFERENCES conversations(id)\n                               ON DELETE CASCADE ON UPDATE CASCADE,\n  purpose                  TEXT NOT NULL,\n  provider                 TEXT NOT NULL,\n  model                    TEXT NOT NULL,\n  requested_output_cap     INTEGER NOT NULL CHECK(requested_output_cap > 0),\n  estimated_input_tokens   INTEGER NOT NULL CHECK(estimated_input_tokens >= 0),\n  status                   TEXT NOT NULL\n                                CHECK(status IN ('started','succeeded','failed','cancelled','stale','timed_out')),\n  started_at               DATETIME NOT NULL,\n  finished_at              DATETIME,\n  elapsed_ms               INTEGER CHECK(elapsed_ms >= 0),\n  pricing_provenance_json  TEXT,\n  provider_usage_json      TEXT\n)",
            "CREATE TABLE console_conversation_capture_policy(\n  conversation_id TEXT PRIMARY KEY NOT NULL\n    REFERENCES conversations(id) ON DELETE CASCADE,\n  capture_detail TEXT NULL CHECK (capture_detail IN ('safe', 'full')),\n  capture_enabled INTEGER NULL CHECK (capture_enabled IN (0, 1)),\n  pii_redaction_enabled INTEGER NULL CHECK (pii_redaction_enabled IN (0, 1)),\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK (\n    capture_detail IS NOT NULL\n    OR capture_enabled IS NOT NULL\n    OR pii_redaction_enabled IS NOT NULL\n  )\n)",
            "CREATE TABLE console_conversation_context_policy(\n  conversation_id      TEXT PRIMARY KEY\n                            REFERENCES conversations(id)\n                            ON DELETE CASCADE ON UPDATE CASCADE,\n  budget_mode          TEXT CHECK(budget_mode IN ('automatic','custom')),\n  custom_budget_tokens INTEGER CHECK(custom_budget_tokens > 0),\n  compaction_mode      TEXT CHECK(compaction_mode IN ('ask','automatic','off')),\n  trigger_ratio        REAL CHECK(trigger_ratio > 0 AND trigger_ratio <= 0.95),\n  target_ratio         REAL CHECK(target_ratio > 0 AND target_ratio < 1),\n  summary_max_tokens   INTEGER CHECK(summary_max_tokens > 0),\n  failure_behavior     TEXT CHECK(failure_behavior IN ('stop_and_ask','omit_older_context')),\n  carry_forward_mode   TEXT CHECK(carry_forward_mode IN ('memory_with_recent_turns','memory_with_latest_exchange')),\n  policy_revision      INTEGER NOT NULL DEFAULT 1 CHECK(policy_revision > 0),\n  updated_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n, compaction_representation TEXT\n    CHECK(compaction_representation IN ('text_summary','visual_transcript','hybrid')))",
            "CREATE TABLE console_conversation_library_policy (\n    conversation_id TEXT PRIMARY KEY\n        REFERENCES conversations(id)\n        ON DELETE CASCADE ON UPDATE CASCADE,\n    schema_version INTEGER NOT NULL DEFAULT 1\n        CHECK(schema_version > 0),\n    auto_retrieve_on_send INTEGER NOT NULL DEFAULT 0\n        CHECK(auto_retrieve_on_send IN (0, 1)),\n    assistant_library_access INTEGER NOT NULL DEFAULT 0\n        CHECK(assistant_library_access IN (0, 1)),\n    policy_revision INTEGER NOT NULL DEFAULT 1\n        CHECK(policy_revision > 0),\n    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE console_conversation_memories(\n  id                       TEXT PRIMARY KEY,\n  conversation_id          TEXT NOT NULL\n                               REFERENCES conversations(id)\n                               ON DELETE CASCADE ON UPDATE CASCADE,\n  boundary_message_id      TEXT,\n  captured_leaf_message_id TEXT,\n  lineage_json             TEXT NOT NULL DEFAULT '[]',\n  summary_text             TEXT NOT NULL,\n  provider                 TEXT,\n  model                    TEXT,\n  prompt_id                TEXT,\n  prompt_revision          INTEGER CHECK(prompt_revision > 0),\n  prompt_digest            TEXT,\n  selected_units_json      TEXT NOT NULL DEFAULT '[]',\n  summarized_prefix_digest TEXT,\n  input_tokens             INTEGER CHECK(input_tokens >= 0),\n  output_tokens            INTEGER CHECK(output_tokens >= 0),\n  before_tokens            INTEGER CHECK(before_tokens >= 0),\n  after_tokens             INTEGER CHECK(after_tokens >= 0),\n  created_at               DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  revision                 INTEGER NOT NULL DEFAULT 1 CHECK(revision > 0),\n  active                   INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),\n  source_kind              TEXT NOT NULL DEFAULT 'generated'\n                                CHECK(source_kind IN ('generated','legacy')),\n  reset_at                 DATETIME,\n  FOREIGN KEY (conversation_id, boundary_message_id)\n    REFERENCES messages(conversation_id, id)\n    ON DELETE CASCADE ON UPDATE CASCADE,\n  FOREIGN KEY (conversation_id, captured_leaf_message_id)\n    REFERENCES messages(conversation_id, id)\n    ON DELETE CASCADE ON UPDATE CASCADE\n)",
            "CREATE TABLE console_conversation_memory_scopes(\n  memory_id                   TEXT NOT NULL,\n  conversation_id             TEXT NOT NULL\n                                  REFERENCES conversations(id)\n                                  ON DELETE CASCADE ON UPDATE CASCADE,\n  coverage_kind               TEXT NOT NULL\n                                  CHECK(coverage_kind IN ('prefix', 'range')),\n  origin_kind                 TEXT NOT NULL\n                                  CHECK(origin_kind IN ('automatic', 'manual_rewind')),\n  selection_anchor_message_id TEXT,\n  PRIMARY KEY (memory_id),\n  FOREIGN KEY (memory_id, conversation_id)\n    REFERENCES console_conversation_memories(id, conversation_id)\n    ON DELETE CASCADE ON UPDATE CASCADE,\n  FOREIGN KEY (conversation_id, selection_anchor_message_id)\n    REFERENCES messages(conversation_id, id)\n    ON DELETE RESTRICT ON UPDATE CASCADE,\n  CHECK(\n    (origin_kind = 'automatic'\n      AND coverage_kind = 'prefix'\n      AND selection_anchor_message_id IS NULL)\n    OR\n    (origin_kind = 'manual_rewind'\n      AND selection_anchor_message_id IS NOT NULL)\n  )\n)",
            "CREATE TABLE console_conversation_memory_selections(\n  sequence              INTEGER PRIMARY KEY AUTOINCREMENT,\n  selection_id          TEXT NOT NULL UNIQUE,\n  conversation_id       TEXT NOT NULL\n                           REFERENCES conversations(id)\n                           ON DELETE CASCADE ON UPDATE CASCADE,\n  activation_message_id TEXT NOT NULL,\n  selected_memory_id    TEXT,\n  event_kind            TEXT NOT NULL CHECK(event_kind IN ('select', 'reset')),\n  suppresses_legacy     INTEGER NOT NULL DEFAULT 0 CHECK(suppresses_legacy IN (0, 1)),\n  created_at            DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  revision              INTEGER NOT NULL DEFAULT 1 CHECK(revision > 0),\n  active                INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0, 1)),\n  FOREIGN KEY (conversation_id, activation_message_id)\n    REFERENCES messages(conversation_id, id)\n    ON DELETE RESTRICT ON UPDATE CASCADE,\n  FOREIGN KEY (selected_memory_id, conversation_id)\n    REFERENCES console_conversation_memories(id, conversation_id)\n    ON DELETE RESTRICT ON UPDATE CASCADE,\n  CHECK(\n    (event_kind = 'select' AND selected_memory_id IS NOT NULL)\n    OR\n    (event_kind = 'reset' AND selected_memory_id IS NULL)\n  )\n)",
            "CREATE TABLE console_dispatch_checkpoints (\n    assistant_message_id TEXT PRIMARY KEY\n        REFERENCES messages(id) ON DELETE CASCADE,\n    user_message_id TEXT NOT NULL\n        REFERENCES messages(id) ON DELETE CASCADE,\n    conversation_id TEXT NOT NULL\n        REFERENCES conversations(id) ON DELETE CASCADE,\n    schema_version INTEGER NOT NULL DEFAULT 1\n        CHECK(schema_version > 0),\n    preparation_id TEXT NOT NULL UNIQUE,\n    attempt_id TEXT NOT NULL,\n    state TEXT NOT NULL\n        CHECK(state IN ('accepted', 'dispatch_started')),\n    checkpoint_revision INTEGER NOT NULL DEFAULT 1\n        CHECK(checkpoint_revision > 0),\n    user_message_version INTEGER NOT NULL\n        CHECK(user_message_version > 0),\n    assistant_message_version INTEGER NOT NULL\n        CHECK(assistant_message_version > 0),\n    origin TEXT NOT NULL CHECK(origin IN ('manual', 'queued')),\n    queue_entry_id TEXT,\n    frozen_authority_json TEXT NOT NULL,\n    resolved_destination_json TEXT NOT NULL,\n    reconstructability_json TEXT NOT NULL,\n    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE console_trace_artifacts(\n  artifact_id TEXT PRIMARY KEY NOT NULL,\n  identity_digest TEXT NOT NULL\n    CHECK(length(identity_digest) = 64)\n    CHECK(identity_digest NOT GLOB '*[^0-9a-f]*'),\n  media_type TEXT NOT NULL CHECK(length(media_type) > 0),\n  normalization_version TEXT NOT NULL CHECK(length(normalization_version) > 0),\n  sanitized_bytes BLOB NOT NULL,\n  byte_length INTEGER NOT NULL CHECK(byte_length >= 0),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(typeof(sanitized_bytes) = 'blob'),\n  CHECK(length(sanitized_bytes) = byte_length)\n)",
            "CREATE TABLE console_trace_calls(\n  call_id TEXT PRIMARY KEY NOT NULL,\n  owner_id TEXT NOT NULL REFERENCES console_trace_owners(owner_id),\n  segment_id TEXT NOT NULL REFERENCES console_trace_segments(segment_id),\n  turn_id TEXT NOT NULL,\n  run_id TEXT NOT NULL,\n  call_sequence INTEGER NOT NULL CHECK(call_sequence >= 0),\n  idempotency_key TEXT NOT NULL CHECK(length(idempotency_key) > 0),\n  policy_id TEXT NOT NULL REFERENCES console_trace_policies(policy_id),\n  state TEXT NOT NULL DEFAULT 'reserved' CHECK(state IN (\n    'reserved', 'not_dispatched', 'dispatch_started', 'dispatch_unknown',\n    'response_started', 'complete', 'stopped', 'error', 'interrupted',\n    'abandoned'\n  )),\n  surface_node_id TEXT DEFAULT NULL REFERENCES console_trace_surface_nodes(node_id),\n  request_header_id TEXT DEFAULT NULL\n    REFERENCES console_trace_request_headers(header_id),\n  provider_name TEXT DEFAULT NULL,\n  model_name TEXT DEFAULT NULL,\n  route_identity TEXT DEFAULT NULL,\n  dispatch_started_at TEXT DEFAULT NULL,\n  response_started_at TEXT DEFAULT NULL,\n  settled_at TEXT DEFAULT NULL,\n  provider_inactive_at TEXT DEFAULT NULL,\n  outcome TEXT DEFAULT NULL CHECK(outcome IS NULL OR outcome IN (\n    'complete', 'stopped', 'error', 'interrupted', 'abandoned'\n  )),\n  usage_json TEXT DEFAULT NULL\n    CHECK(usage_json IS NULL OR\n          (json_valid(usage_json) AND json_type(usage_json) = 'object')),\n  integrity_state TEXT NOT NULL DEFAULT 'pending'\n    CHECK(integrity_state IN ('pending', 'complete', 'incomplete')),\n  omission_reason_code TEXT DEFAULT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reservation_provenance TEXT NOT NULL\n  DEFAULT 'crash_durable_reserved'\n  CHECK(reservation_provenance IN (\n    'crash_durable_reserved', 'post_dispatch_promoted'\n  )), import_reason_code TEXT DEFAULT NULL\n  CHECK(import_reason_code IS NULL OR\n        import_reason_code = 'provisional_voice_promoted'),\n  CHECK(\n    (surface_node_id IS NULL AND request_header_id IS NULL) OR\n    (surface_node_id IS NOT NULL AND request_header_id IS NOT NULL)\n  ),\n  CHECK(\n    (provider_name IS NULL AND model_name IS NULL AND route_identity IS NULL) OR\n    (provider_name IS NOT NULL AND model_name IS NOT NULL AND\n     route_identity IS NOT NULL)\n  ),\n  CHECK(\n    state IN ('reserved', 'not_dispatched') OR\n    (surface_node_id IS NOT NULL AND request_header_id IS NOT NULL AND\n     provider_name IS NOT NULL AND dispatch_started_at IS NOT NULL)\n  ),\n  CHECK(\n    (state IN ('complete', 'stopped', 'error', 'interrupted', 'abandoned') AND\n     outcome = state) OR\n    (state NOT IN ('complete', 'stopped', 'error', 'interrupted', 'abandoned') AND\n     outcome IS NULL)\n  ),\n  CHECK(\n    (state = 'reserved' AND dispatch_started_at IS NULL AND\n     response_started_at IS NULL AND settled_at IS NULL AND\n     provider_inactive_at IS NULL) OR\n    (state = 'not_dispatched' AND dispatch_started_at IS NULL AND\n     response_started_at IS NULL AND settled_at IS NOT NULL AND\n     provider_inactive_at IS NULL) OR\n    (state = 'dispatch_started' AND dispatch_started_at IS NOT NULL AND\n     response_started_at IS NULL AND settled_at IS NULL AND\n     provider_inactive_at IS NULL) OR\n    (state = 'dispatch_unknown' AND dispatch_started_at IS NOT NULL AND\n     response_started_at IS NULL AND settled_at IS NOT NULL AND\n     provider_inactive_at IS NULL) OR\n    (state = 'response_started' AND dispatch_started_at IS NOT NULL AND\n     response_started_at IS NOT NULL AND settled_at IS NULL AND\n     provider_inactive_at IS NULL) OR\n    (state IN ('complete', 'stopped', 'interrupted') AND\n     dispatch_started_at IS NOT NULL AND response_started_at IS NOT NULL AND\n     settled_at IS NOT NULL AND provider_inactive_at IS NULL) OR\n    (state = 'error' AND dispatch_started_at IS NOT NULL AND\n     settled_at IS NOT NULL AND provider_inactive_at IS NULL) OR\n    (state = 'abandoned' AND dispatch_started_at IS NOT NULL AND\n     response_started_at IS NULL AND settled_at IS NOT NULL AND\n     provider_inactive_at IS NOT NULL)\n  ),\n  CHECK(\n    usage_json IS NULL OR\n    state IN ('complete', 'stopped', 'error', 'interrupted', 'abandoned')\n  )\n)",
            "CREATE TABLE console_trace_compaction_state(\n  singleton_id INTEGER PRIMARY KEY NOT NULL CHECK(singleton_id = 1),\n  status TEXT NOT NULL DEFAULT 'pending'\n    CHECK(status IN ('pending', 'running', 'complete')),\n  reason_code TEXT NOT NULL DEFAULT 'awaiting_gc'\n    CHECK(length(reason_code) BETWEEN 1 AND 64),\n  last_gc_request_id TEXT DEFAULT NULL\n    CHECK(last_gc_request_id IS NULL OR length(last_gc_request_id) BETWEEN 1 AND 128),\n  attempt_id TEXT DEFAULT NULL\n    CHECK(attempt_id IS NULL OR length(attempt_id) BETWEEN 1 AND 128),\n  retry_count INTEGER NOT NULL DEFAULT 0 CHECK(retry_count BETWEEN 0 AND 32),\n  next_retry_at TEXT DEFAULT NULL,\n  progress_basis_points INTEGER NOT NULL DEFAULT 0\n    CHECK(progress_basis_points BETWEEN 0 AND 10000),\n  allocated_bytes_before INTEGER NOT NULL DEFAULT 0 CHECK(allocated_bytes_before >= 0),\n  allocated_bytes_after INTEGER NOT NULL DEFAULT 0 CHECK(allocated_bytes_after >= 0),\n  freelist_bytes_before INTEGER NOT NULL DEFAULT 0 CHECK(freelist_bytes_before >= 0),\n  freelist_bytes_after INTEGER NOT NULL DEFAULT 0 CHECK(freelist_bytes_after >= 0),\n  wal_bytes_before INTEGER NOT NULL DEFAULT 0 CHECK(wal_bytes_before >= 0),\n  wal_bytes_after INTEGER NOT NULL DEFAULT 0 CHECK(wal_bytes_after >= 0),\n  logical_live_bytes INTEGER NOT NULL DEFAULT 0 CHECK(logical_live_bytes >= 0),\n  started_at TEXT DEFAULT NULL,\n  completed_at TEXT DEFAULT NULL,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE console_trace_events(\n  event_id TEXT PRIMARY KEY NOT NULL,\n  segment_id TEXT NOT NULL REFERENCES console_trace_segments(segment_id),\n  sequence INTEGER NOT NULL CHECK(sequence >= 0),\n  event_type TEXT NOT NULL CHECK(event_type IN (\n    'turn_boundary', 'call_boundary', 'surface_append', 'surface_replace',\n    'tool_call', 'tool_result', 'request_header_selection',\n    'provider_route_selection', 'response_selection', 'call_outcome',\n    'usage', 'gap'\n  )),\n  turn_id TEXT DEFAULT NULL,\n  call_id TEXT DEFAULT NULL REFERENCES console_trace_calls(call_id),\n  surface_node_id TEXT DEFAULT NULL REFERENCES console_trace_surface_nodes(node_id),\n  surface_replacement_id TEXT DEFAULT NULL\n    REFERENCES console_trace_surface_replacements(replacement_id),\n  request_header_id TEXT DEFAULT NULL\n    REFERENCES console_trace_request_headers(header_id),\n  semantic_revision_id TEXT DEFAULT NULL\n    REFERENCES console_trace_semantic_revisions(revision_id),\n  artifact_id TEXT DEFAULT NULL REFERENCES console_trace_artifacts(artifact_id),\n  omission_reason_code TEXT DEFAULT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(segment_id, sequence),\n  CHECK(semantic_revision_id IS NULL OR artifact_id IS NULL),\n  CHECK(event_type <> 'surface_append' OR surface_node_id IS NOT NULL),\n  CHECK(event_type <> 'surface_replace' OR surface_replacement_id IS NOT NULL),\n  CHECK(event_type <> 'request_header_selection' OR request_header_id IS NOT NULL),\n  CHECK(event_type NOT IN (\n    'call_boundary', 'response_selection', 'call_outcome', 'usage'\n  ) OR call_id IS NOT NULL),\n  CHECK(event_type <> 'gap' OR omission_reason_code IS NOT NULL)\n)",
            "CREATE TABLE console_trace_gc_marks(\n  request_id TEXT NOT NULL REFERENCES console_trace_gc_runs(request_id),\n  entity_kind TEXT NOT NULL CHECK(length(entity_kind) > 0),\n  entity_id TEXT NOT NULL CHECK(length(entity_id) > 0),\n  marked_epoch INTEGER NOT NULL CHECK(marked_epoch >= 0),\n  PRIMARY KEY(request_id, entity_kind, entity_id)\n)",
            "CREATE TABLE console_trace_gc_runs(\n  request_id TEXT PRIMARY KEY NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending'\n    CHECK(status IN ('pending', 'marked', 'completed', 'stale_epoch')),\n  operation_kind TEXT NOT NULL DEFAULT 'collect'\n    CHECK(operation_kind IN ('collect', 'purge_conversation')),\n  target_conversation_id TEXT DEFAULT NULL,\n  target_owner_id TEXT DEFAULT NULL,\n  target_root_segment_id TEXT DEFAULT NULL,\n  marked_epoch INTEGER DEFAULT NULL CHECK(marked_epoch IS NULL OR marked_epoch >= 0),\n  swept_epoch INTEGER DEFAULT NULL CHECK(swept_epoch IS NULL OR swept_epoch >= 0),\n  result_json TEXT DEFAULT NULL\n    CHECK(result_json IS NULL OR (json_valid(result_json) AND json_type(result_json) = 'object')),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(\n    (operation_kind = 'collect'\n      AND target_conversation_id IS NULL\n      AND target_owner_id IS NULL\n      AND target_root_segment_id IS NULL)\n    OR\n    (operation_kind = 'purge_conversation'\n      AND length(target_conversation_id) > 0\n      AND length(target_owner_id) > 0\n      AND length(target_root_segment_id) > 0)\n  )\n)",
            "CREATE TABLE console_trace_gc_segment_scopes(\n  request_id TEXT NOT NULL REFERENCES console_trace_gc_runs(request_id),\n  segment_id TEXT NOT NULL REFERENCES console_trace_segments(segment_id),\n  through_sequence INTEGER DEFAULT NULL\n    CHECK(through_sequence IS NULL OR through_sequence >= 0),\n  PRIMARY KEY(request_id, segment_id)\n)",
            "CREATE TABLE console_trace_graph_epoch(\n  singleton_id INTEGER PRIMARY KEY NOT NULL CHECK(singleton_id = 1),\n  epoch INTEGER NOT NULL DEFAULT 0 CHECK(epoch >= 0),\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE console_trace_header_components(\n  header_id TEXT NOT NULL REFERENCES console_trace_request_headers(header_id),\n  component_kind TEXT NOT NULL CHECK(length(component_kind) > 0),\n  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),\n  artifact_id TEXT NOT NULL REFERENCES console_trace_artifacts(artifact_id),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY(header_id, component_kind, ordinal)\n)",
            "CREATE TABLE console_trace_maintenance_state(\n  singleton_id INTEGER PRIMARY KEY NOT NULL CHECK(singleton_id = 1),\n  state TEXT NOT NULL DEFAULT 'idle'\n    CHECK(state IN ('idle', 'marking', 'sweeping', 'compacting')),\n  lease_id TEXT DEFAULT NULL,\n  lease_owner TEXT DEFAULT NULL,\n  lease_expires_at TEXT DEFAULT NULL,\n  marked_epoch INTEGER DEFAULT NULL CHECK(marked_epoch IS NULL OR marked_epoch >= 0),\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(\n    (state = 'idle' AND lease_id IS NULL AND lease_owner IS NULL AND\n     lease_expires_at IS NULL AND marked_epoch IS NULL) OR\n    (state <> 'idle' AND lease_id IS NOT NULL AND lease_owner IS NOT NULL AND\n     lease_expires_at IS NOT NULL)\n  )\n)",
            "CREATE TABLE console_trace_migration_state(\n  migration_name TEXT PRIMARY KEY NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending'\n    CHECK(status IN ('pending', 'running', 'logical_complete', 'failed')),\n  last_exchange_id INTEGER DEFAULT NULL CHECK(last_exchange_id IS NULL OR last_exchange_id >= 0),\n  processed_rows INTEGER NOT NULL DEFAULT 0 CHECK(processed_rows >= 0),\n  processed_bytes INTEGER NOT NULL DEFAULT 0 CHECK(processed_bytes >= 0),\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE console_trace_owners(\n  owner_id TEXT PRIMARY KEY NOT NULL,\n  conversation_id TEXT UNIQUE DEFAULT NULL\n    REFERENCES conversations(id) ON DELETE SET NULL,\n  root_segment_id TEXT NOT NULL REFERENCES console_trace_segments(segment_id),\n  attached INTEGER NOT NULL DEFAULT 1 CHECK(attached IN (0, 1)),\n  detached_at TEXT DEFAULT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(\n    (attached = 1 AND conversation_id IS NOT NULL AND detached_at IS NULL) OR\n    (attached = 0 AND conversation_id IS NULL AND detached_at IS NOT NULL)\n  )\n)",
            "CREATE TABLE console_trace_policies(\n  policy_id TEXT PRIMARY KEY NOT NULL,\n  credential_filter_version TEXT NOT NULL CHECK(length(credential_filter_version) > 0),\n  pii_redaction_enabled INTEGER NOT NULL DEFAULT 0\n    CHECK(pii_redaction_enabled IN (0, 1)),\n  pii_ruleset_revision_id TEXT DEFAULT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(\n    (pii_redaction_enabled = 0) OR\n    (pii_redaction_enabled = 1 AND pii_ruleset_revision_id IS NOT NULL)\n  )\n)",
            "CREATE TABLE console_trace_redaction_spans(\n  span_id TEXT PRIMARY KEY NOT NULL,\n  policy_id TEXT NOT NULL REFERENCES console_trace_policies(policy_id),\n  source_kind TEXT NOT NULL CHECK(source_kind IN ('revision', 'artifact')),\n  semantic_revision_id TEXT DEFAULT NULL\n    REFERENCES console_trace_semantic_revisions(revision_id),\n  artifact_id TEXT DEFAULT NULL REFERENCES console_trace_artifacts(artifact_id),\n  field_path TEXT NOT NULL CHECK(length(field_path) > 0),\n  start_codepoint INTEGER NOT NULL CHECK(start_codepoint >= 0),\n  end_codepoint INTEGER NOT NULL CHECK(end_codepoint > start_codepoint),\n  category TEXT NOT NULL CHECK(length(category) > 0),\n  rule_id TEXT NOT NULL CHECK(length(rule_id) > 0),\n  detector_version TEXT NOT NULL CHECK(length(detector_version) > 0),\n  outcome TEXT NOT NULL CHECK(outcome IN ('applied', 'omitted', 'unavailable')),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(\n    (source_kind = 'revision' AND semantic_revision_id IS NOT NULL AND\n     artifact_id IS NULL) OR\n    (source_kind = 'artifact' AND semantic_revision_id IS NULL AND\n     artifact_id IS NOT NULL)\n  )\n)",
            "CREATE TABLE console_trace_request_headers(\n  header_id TEXT PRIMARY KEY NOT NULL,\n  provider_name TEXT NOT NULL CHECK(length(provider_name) > 0),\n  model_name TEXT NOT NULL CHECK(length(model_name) > 0),\n  route_identity TEXT NOT NULL CHECK(length(route_identity) > 0),\n  endpoint_identity TEXT NOT NULL CHECK(length(endpoint_identity) > 0),\n  generation_parameters_json TEXT NOT NULL,\n  adapter_defaults_json TEXT NOT NULL,\n  response_format_json TEXT NOT NULL,\n  reasoning_controls_json TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(json_valid(generation_parameters_json) AND\n        json_type(generation_parameters_json) = 'object'),\n  CHECK(json_valid(adapter_defaults_json) AND\n        json_type(adapter_defaults_json) = 'object'),\n  CHECK(json_valid(response_format_json) AND\n        json_type(response_format_json) = 'object'),\n  CHECK(json_valid(reasoning_controls_json) AND\n        json_type(reasoning_controls_json) = 'object')\n)",
            "CREATE TABLE console_trace_response_links(\n  response_link_id TEXT PRIMARY KEY NOT NULL,\n  call_id TEXT NOT NULL UNIQUE REFERENCES console_trace_calls(call_id),\n  link_kind TEXT NOT NULL CHECK(link_kind IN ('revision', 'artifact')),\n  semantic_revision_id TEXT DEFAULT NULL\n    REFERENCES console_trace_semantic_revisions(revision_id),\n  artifact_id TEXT DEFAULT NULL REFERENCES console_trace_artifacts(artifact_id),\n  verification_outcome TEXT NOT NULL\n    CHECK(verification_outcome IN ('verified_equal', 'sanitized_artifact')),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(\n    (link_kind = 'revision' AND semantic_revision_id IS NOT NULL AND\n     artifact_id IS NULL AND verification_outcome = 'verified_equal') OR\n    (link_kind = 'artifact' AND semantic_revision_id IS NULL AND\n     artifact_id IS NOT NULL AND verification_outcome = 'sanitized_artifact')\n  )\n)",
            "CREATE TABLE console_trace_retention_roots(\n  retention_id TEXT PRIMARY KEY NOT NULL,\n  entity_kind TEXT NOT NULL\n    CHECK(entity_kind IN ('owner', 'call', 'revision', 'artifact')),\n  entity_id TEXT NOT NULL CHECK(length(entity_id) > 0),\n  retain_until TEXT NOT NULL CHECK(length(retain_until) > 0),\n  reason_code TEXT NOT NULL CHECK(length(reason_code) > 0),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(entity_kind, entity_id, reason_code)\n)",
            "CREATE TABLE console_trace_revision_bindings(\n  revision_id TEXT NOT NULL\n    REFERENCES console_trace_semantic_revisions(revision_id),\n  policy_id TEXT NOT NULL REFERENCES console_trace_policies(policy_id),\n  binding_outcome TEXT NOT NULL CHECK(binding_outcome IN ('artifact', 'omission')),\n  artifact_id TEXT DEFAULT NULL REFERENCES console_trace_artifacts(artifact_id),\n  omission_reason_code TEXT DEFAULT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY(revision_id, policy_id),\n  CHECK(\n    (binding_outcome = 'artifact' AND artifact_id IS NOT NULL AND\n     omission_reason_code IS NULL) OR\n    (binding_outcome = 'omission' AND artifact_id IS NULL AND\n     omission_reason_code IS NOT NULL AND length(omission_reason_code) > 0)\n  )\n)",
            "CREATE TABLE console_trace_segments(\n  segment_id TEXT PRIMARY KEY NOT NULL,\n  parent_segment_id TEXT DEFAULT NULL,\n  inherited_through_sequence INTEGER DEFAULT NULL,\n  inherited_surface_head_id TEXT DEFAULT NULL\n    REFERENCES console_trace_surface_nodes(node_id),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(\n    (parent_segment_id IS NULL AND inherited_through_sequence IS NULL AND\n     inherited_surface_head_id IS NULL) OR\n    (parent_segment_id IS NOT NULL AND inherited_through_sequence >= 0 AND\n     inherited_surface_head_id IS NOT NULL)\n  ),\n  CHECK(parent_segment_id IS NULL OR parent_segment_id <> segment_id),\n  FOREIGN KEY(parent_segment_id, inherited_through_sequence)\n    REFERENCES console_trace_events(segment_id, sequence)\n)",
            "CREATE TABLE console_trace_semantic_revisions(\n  revision_id TEXT PRIMARY KEY NOT NULL,\n  source_conversation_id TEXT NOT NULL,\n  source_message_id TEXT NOT NULL,\n  revision_sequence INTEGER NOT NULL CHECK(revision_sequence >= 0),\n  normalized_role TEXT NOT NULL CHECK(length(normalized_role) > 0),\n  content_kind TEXT NOT NULL CHECK(length(content_kind) > 0),\n  creation_reason TEXT NOT NULL CHECK(length(creation_reason) > 0),\n  predecessor_revision_id TEXT DEFAULT NULL\n    REFERENCES console_trace_semantic_revisions(revision_id),\n  live_message_id TEXT DEFAULT NULL REFERENCES messages(id) ON DELETE RESTRICT,\n  live_locator_retired_at TEXT DEFAULT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CHECK(predecessor_revision_id IS NULL OR predecessor_revision_id <> revision_id),\n  CHECK(\n    (predecessor_revision_id IS NULL AND revision_sequence = 0) OR\n    (predecessor_revision_id IS NOT NULL AND revision_sequence > 0)\n  ),\n  CHECK(live_message_id IS NULL OR live_message_id = source_message_id),\n  CHECK(\n    (live_message_id IS NOT NULL AND live_locator_retired_at IS NULL) OR\n    (live_message_id IS NULL AND live_locator_retired_at IS NOT NULL)\n  ),\n  UNIQUE(source_message_id, revision_sequence)\n)",
            "CREATE TABLE console_trace_surface_nodes(\n  node_id TEXT PRIMARY KEY NOT NULL,\n  segment_id TEXT NOT NULL REFERENCES console_trace_segments(segment_id),\n  sequence INTEGER NOT NULL CHECK(sequence >= 0),\n  predecessor_node_id TEXT DEFAULT NULL\n    REFERENCES console_trace_surface_nodes(node_id),\n  component_kind TEXT NOT NULL CHECK(length(component_kind) > 0),\n  reference_kind TEXT NOT NULL\n    CHECK(reference_kind IN ('revision', 'artifact', 'omission')),\n  semantic_revision_id TEXT DEFAULT NULL\n    REFERENCES console_trace_semantic_revisions(revision_id),\n  artifact_id TEXT DEFAULT NULL REFERENCES console_trace_artifacts(artifact_id),\n  omission_reason_code TEXT DEFAULT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(segment_id, sequence),\n  UNIQUE(node_id, sequence),\n  CHECK(\n    (reference_kind = 'revision' AND semantic_revision_id IS NOT NULL AND\n     artifact_id IS NULL AND omission_reason_code IS NULL) OR\n    (reference_kind = 'artifact' AND semantic_revision_id IS NULL AND\n     artifact_id IS NOT NULL AND omission_reason_code IS NULL) OR\n    (reference_kind = 'omission' AND semantic_revision_id IS NULL AND\n     artifact_id IS NULL AND omission_reason_code IS NOT NULL AND\n     length(omission_reason_code) > 0)\n  )\n)",
            "CREATE TABLE console_trace_surface_replacements(\n  replacement_id TEXT PRIMARY KEY NOT NULL,\n  segment_id TEXT NOT NULL REFERENCES console_trace_segments(segment_id),\n  predecessor_head_id TEXT NOT NULL\n    REFERENCES console_trace_surface_nodes(node_id),\n  start_node_id TEXT NOT NULL,\n  start_sequence INTEGER NOT NULL CHECK(start_sequence >= 0),\n  end_node_id TEXT NOT NULL,\n  end_sequence INTEGER NOT NULL CHECK(end_sequence >= 0),\n  replacement_node_id TEXT NOT NULL\n    REFERENCES console_trace_surface_nodes(node_id),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY(start_node_id, start_sequence)\n    REFERENCES console_trace_surface_nodes(node_id, sequence),\n  FOREIGN KEY(end_node_id, end_sequence)\n    REFERENCES console_trace_surface_nodes(node_id, sequence),\n  CHECK(end_sequence >= start_sequence)\n)",
            "CREATE TABLE conversation_dictionaries(\n  conversation_id INTEGER NOT NULL REFERENCES conversations(id),\n  dictionary_id   INTEGER NOT NULL REFERENCES chat_dictionaries(id),\n  priority        INTEGER NOT NULL DEFAULT 0,\n  PRIMARY KEY (conversation_id, dictionary_id)\n)",
            "CREATE TABLE conversation_dictionary_attachments(\n  conversation_id TEXT    NOT NULL REFERENCES conversations(id)\n                            ON DELETE CASCADE ON UPDATE CASCADE,\n  dictionary_id   INTEGER NOT NULL,\n  PRIMARY KEY (conversation_id, dictionary_id)\n)",
            "CREATE TABLE conversation_dictionary_unresolved(\n  conversation_id TEXT PRIMARY KEY REFERENCES conversations(id)\n                        ON DELETE CASCADE ON UPDATE CASCADE\n)",
            "CREATE TABLE conversation_keywords(\n  conversation_id TEXT    NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n  keyword_id      INTEGER NOT NULL REFERENCES keywords(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY(conversation_id,keyword_id)\n)",
            "CREATE TABLE conversation_local_marks (\n  conversation_id TEXT NOT NULL,\n  mark_type TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  PRIMARY KEY (conversation_id, mark_type)\n)",
            "CREATE TABLE conversation_world_books(\n  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n  world_book_id   INTEGER NOT NULL REFERENCES world_books(id) ON DELETE CASCADE,\n  priority        INTEGER NOT NULL DEFAULT 0,\n  PRIMARY KEY (conversation_id, world_book_id)\n)",
            "CREATE TABLE conversations(\n  id                     TEXT PRIMARY KEY,            /* UUID */\n  root_id                TEXT NOT NULL,\n  forked_from_message_id TEXT REFERENCES messages(id) ON DELETE SET NULL,\n  parent_conversation_id TEXT REFERENCES conversations(id) ON DELETE SET NULL,\n  character_id           INTEGER REFERENCES character_cards(id)\n                          ON DELETE CASCADE ON UPDATE CASCADE,\n  title        TEXT,\n  rating       INTEGER CHECK(rating BETWEEN 1 AND 5),\n  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_modified DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted      BOOLEAN  NOT NULL DEFAULT 0,\n  client_id    TEXT     NOT NULL,\n  version      INTEGER  NOT NULL DEFAULT 1,\n  console_project_context_json TEXT\n, assistant_kind TEXT, assistant_id TEXT, persona_memory_mode TEXT, scope_type TEXT NOT NULL DEFAULT 'global', workspace_id TEXT, state TEXT NOT NULL DEFAULT 'in-progress', topic_label TEXT, topic_label_source TEXT, topic_last_tagged_at TEXT, topic_last_tagged_message_id TEXT, cluster_id TEXT, source TEXT, external_ref TEXT, runtime_backend TEXT NOT NULL DEFAULT 'local', discovery_owner TEXT NOT NULL DEFAULT 'general_chat', discovery_entity_id TEXT, system_prompt TEXT, metadata TEXT, active_leaf_message_id TEXT, context_summary TEXT, summary_boundary_message_id TEXT, assistant_authority_id TEXT\n  CHECK(\n    assistant_authority_id IS NULL\n    OR (\n      typeof(assistant_authority_id) = 'text'\n      AND length(CAST(assistant_authority_id AS BLOB)) BETWEEN 1 AND 256\n    )\n  ), thinking_history_policy TEXT DEFAULT NULL\n    CHECK(\n        thinking_history_policy IS NULL OR\n        thinking_history_policy IN ('auto', 'include', 'exclude')\n    ), active_leaf_before_message_id TEXT, archived INTEGER NOT NULL DEFAULT 0\n    CHECK (archived IN (0, 1)))",
            "CREATE VIRTUAL TABLE conversations_fts\nUSING fts5(\n  title,\n  content='conversations',\n  content_rowid='rowid'\n)",
            "CREATE TABLE 'conversations_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'conversations_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'conversations_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'conversations_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE db_schema_version(\n  schema_name TEXT PRIMARY KEY NOT NULL,\n  version     INTEGER NOT NULL\n)",
            "CREATE TABLE decks (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL UNIQUE,\n    description TEXT,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    created_by TEXT NOT NULL,\n    last_modified_by TEXT NOT NULL,\n    version INTEGER DEFAULT 1,\n    is_deleted INTEGER DEFAULT 0,\n    card_count INTEGER DEFAULT 0,\n    metadata TEXT     -- JSON for Anki export settings, etc.\n)",
            "CREATE TABLE flashcard_assets (\n    asset_uuid TEXT PRIMARY KEY,\n    original_filename TEXT,\n    mime_type TEXT,\n    byte_size INTEGER NOT NULL DEFAULT 0,\n    content BLOB NOT NULL,\n    client_id TEXT NOT NULL DEFAULT 'unknown',\n    deleted INTEGER NOT NULL DEFAULT 0,\n    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    last_modified TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE flashcard_templates (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    model_type TEXT NOT NULL DEFAULT 'basic',\n    front_template TEXT NOT NULL,\n    back_template TEXT,\n    notes_template TEXT,\n    extra_template TEXT,\n    placeholder_definitions TEXT NOT NULL DEFAULT '[]',\n    client_id TEXT NOT NULL DEFAULT 'unknown',\n    version INTEGER NOT NULL DEFAULT 1,\n    deleted INTEGER NOT NULL DEFAULT 0,\n    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    last_modified TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE flashcards (\n    id TEXT PRIMARY KEY,\n    deck_id TEXT REFERENCES decks(id) ON DELETE CASCADE,\n    front TEXT NOT NULL,  -- Question/prompt\n    back TEXT NOT NULL,   -- Answer\n    tags TEXT,            -- Space-separated tags\n    type TEXT DEFAULT 'basic',  -- basic, cloze, reverse, etc.\n    \n    -- Spaced repetition fields (SM-2 algorithm)\n    interval INTEGER DEFAULT 0,  -- Days until next review\n    repetitions INTEGER DEFAULT 0,\n    ease_factor REAL DEFAULT 2.5,\n    next_review TIMESTAMP,\n    last_review TIMESTAMP,\n    \n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    created_by TEXT NOT NULL,\n    last_modified_by TEXT NOT NULL,\n    version INTEGER DEFAULT 1,\n    is_deleted INTEGER DEFAULT 0,\n    is_suspended INTEGER DEFAULT 0,\n    metadata TEXT     -- JSON for additional Anki fields\n)",
            "CREATE VIRTUAL TABLE flashcards_fts USING fts5(\n    front, back, tags, content=flashcards, content_rowid=rowid\n)",
            "CREATE TABLE 'flashcards_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'flashcards_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'flashcards_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'flashcards_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE kept_briefings(\n  id                     INTEGER PRIMARY KEY AUTOINCREMENT,\n  source_briefing_id     INTEGER NOT NULL UNIQUE,\n  watchlist_name         TEXT,\n  body_markdown          TEXT NOT NULL,\n  covers_through_item_id INTEGER,\n  covers_from_ts         DATETIME,\n  selection_mode         TEXT,\n  model_used             TEXT,\n  item_count             INTEGER NOT NULL DEFAULT 0,\n  featured_count         INTEGER NOT NULL DEFAULT 0,\n  overflow_count         INTEGER NOT NULL DEFAULT 0,\n  origin                 TEXT NOT NULL CHECK(origin IN ('manual','scheduled')),\n  original_created_at    DATETIME,\n  kept_at                DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE kept_scripts(\n  id                   INTEGER PRIMARY KEY AUTOINCREMENT,\n  kept_briefing_id     INTEGER NOT NULL REFERENCES kept_briefings(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  source_script_id     INTEGER UNIQUE,\n  preset_name          TEXT NOT NULL,\n  roster_snapshot_json TEXT NOT NULL,\n  turns_json           TEXT NOT NULL,\n  model_used           TEXT,\n  original_created_at  DATETIME,\n  kept_at              DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE keyword_collections(\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  name          TEXT    UNIQUE NOT NULL COLLATE NOCASE,\n  parent_id     INTEGER REFERENCES keyword_collections(id)\n                         ON DELETE SET NULL ON UPDATE CASCADE,\n  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_modified DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted       BOOLEAN  NOT NULL DEFAULT 0,\n  client_id     TEXT     NOT NULL DEFAULT 'unknown',\n  version       INTEGER  NOT NULL DEFAULT 1\n, sync_id TEXT)",
            "CREATE VIRTUAL TABLE keyword_collections_fts\nUSING fts5(\n  name,\n  content='keyword_collections',\n  content_rowid='id'\n)",
            "CREATE TABLE 'keyword_collections_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'keyword_collections_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'keyword_collections_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'keyword_collections_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE keywords(\n  id            INTEGER PRIMARY KEY AUTOINCREMENT,\n  keyword       TEXT    UNIQUE NOT NULL COLLATE NOCASE,\n  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_modified DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted       BOOLEAN  NOT NULL DEFAULT 0,\n  client_id     TEXT     NOT NULL DEFAULT 'unknown',\n  version       INTEGER  NOT NULL DEFAULT 1\n, sync_id TEXT)",
            "CREATE VIRTUAL TABLE keywords_fts\nUSING fts5(\n  keyword,\n  content='keywords',\n  content_rowid='id'\n)",
            "CREATE TABLE 'keywords_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'keywords_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'keywords_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'keywords_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE learning_paths (\n    id TEXT PRIMARY KEY,\n    title TEXT NOT NULL,\n    description TEXT,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    created_by TEXT NOT NULL,\n    last_modified_by TEXT NOT NULL,\n    version INTEGER DEFAULT 1,\n    is_deleted INTEGER DEFAULT 0,\n    path_order TEXT,  -- JSON array of topic IDs in order\n    metadata TEXT     -- JSON for additional data\n)",
            "CREATE TABLE message_attachments(\n  message_id   TEXT    NOT NULL REFERENCES messages(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  position     INTEGER NOT NULL CHECK (position >= 1),\n  data         BLOB    NOT NULL,\n  mime_type    TEXT    NOT NULL,\n  display_name TEXT    NOT NULL DEFAULT '',\n  PRIMARY KEY (message_id, position)\n)",
            "CREATE TABLE message_exchanges(\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  message_id   TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,\n  run_tag      TEXT NOT NULL,\n  seq          INTEGER NOT NULL,\n  status       TEXT NOT NULL,\n  abandoned    BOOLEAN NOT NULL DEFAULT 0,\n  capture_blob BLOB NOT NULL,\n  created_at   TEXT NOT NULL, capture_detail TEXT NOT NULL DEFAULT 'safe'\nCHECK (capture_detail IN ('safe', 'full')),\n  UNIQUE(message_id, run_tag, seq)\n)",
            "CREATE TABLE message_generation_metadata(\n  message_id      TEXT    NOT NULL REFERENCES messages(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  position        INTEGER NOT NULL CHECK (position >= 0),\n  prompt          TEXT    NOT NULL,\n  negative_prompt TEXT    NOT NULL DEFAULT '',\n  backend         TEXT    NOT NULL,\n  model           TEXT,\n  seed            INTEGER,\n  style           TEXT,\n  params_json     TEXT    NOT NULL DEFAULT '{}',\n  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (message_id, position)\n)",
            "CREATE TABLE message_trajectory_metadata (\n    message_id TEXT NOT NULL,\n    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n    turn_id TEXT NOT NULL,\n    seq INTEGER NOT NULL,\n    event_kind TEXT NOT NULL,\n    step_started_at REAL,\n    first_token_at REAL,\n    completed_at REAL,\n    model TEXT,\n    provider TEXT,\n    payload_json TEXT,\n    PRIMARY KEY (message_id, event_kind, seq),\n    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE\n)",
            "CREATE TABLE messages(\n  id                TEXT PRIMARY KEY,                 /* UUID */\n  conversation_id   TEXT  NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n  parent_message_id TEXT  REFERENCES messages(id)     ON DELETE SET NULL,\n  sender            TEXT  NOT NULL,\n  content           TEXT  NOT NULL, -- Text content of the message\n  image_data        BLOB DEFAULT NULL,\n  image_mime_type   TEXT DEFAULT NULL,\n  timestamp         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  ranking           INTEGER,\n  last_modified     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted           BOOLEAN NOT NULL DEFAULT 0,\n  client_id         TEXT    NOT NULL,\n  version           INTEGER NOT NULL DEFAULT 1\n, feedback TEXT, role TEXT DEFAULT 'assistant', variant_of TEXT REFERENCES messages(id) ON DELETE CASCADE, variant_number INTEGER DEFAULT 1, is_selected_variant BOOLEAN DEFAULT 1, total_variants INTEGER DEFAULT 1, usage_json TEXT DEFAULT NULL, metadata_json TEXT DEFAULT NULL, provider_continuation_json TEXT DEFAULT NULL, assistant_generation_state TEXT\n    CHECK(\n        assistant_generation_state IS NULL OR\n        assistant_generation_state IN (\n            'accepted', 'dispatch_started', 'continuation_active',\n            'complete', 'stopped', 'failed', 'discarded'\n        )\n    ), thinking_blocks_json TEXT DEFAULT NULL)",
            "CREATE VIRTUAL TABLE messages_fts\nUSING fts5(\n  content,\n  content='messages',\n  content_rowid='rowid'\n)",
            "CREATE TABLE 'messages_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'messages_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'messages_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'messages_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE mindmap_nodes (\n    id TEXT PRIMARY KEY,\n    mindmap_id TEXT REFERENCES mindmaps(id) ON DELETE CASCADE,\n    parent_id TEXT REFERENCES mindmap_nodes(id) ON DELETE CASCADE,\n    text TEXT NOT NULL,\n    position_x REAL DEFAULT 0,\n    position_y REAL DEFAULT 0,\n    node_order INTEGER DEFAULT 0,\n    color TEXT,\n    icon TEXT,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    metadata TEXT     -- JSON for additional properties\n)",
            "CREATE VIRTUAL TABLE mindmap_nodes_fts USING fts5(\n    text, content=mindmap_nodes, content_rowid=rowid\n)",
            "CREATE TABLE 'mindmap_nodes_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'mindmap_nodes_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'mindmap_nodes_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'mindmap_nodes_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE mindmaps (\n    id TEXT PRIMARY KEY,\n    title TEXT NOT NULL,\n    root_node_id TEXT,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    created_by TEXT NOT NULL,\n    last_modified_by TEXT NOT NULL,\n    version INTEGER DEFAULT 1,\n    is_deleted INTEGER DEFAULT 0,\n    metadata TEXT     -- JSON for styling, layout preferences\n)",
            "CREATE TABLE note_folder_memberships(\n  id              TEXT PRIMARY KEY,\n  folder_id       TEXT NOT NULL REFERENCES note_folders(id),\n  note_id         TEXT NOT NULL REFERENCES notes(id),\n  ownership       TEXT NOT NULL CHECK(ownership IN ('manual', 'managed')),\n  owner_id        TEXT NOT NULL DEFAULT '',\n  owner_active    INTEGER NOT NULL DEFAULT 1 CHECK(owner_active IN (0, 1)),\n  version         INTEGER NOT NULL DEFAULT 1 CHECK(version >= 1),\n  deleted         INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0, 1)),\n  created_at      TEXT NOT NULL,\n  modified_at     TEXT NOT NULL,\n  CHECK(\n    (ownership = 'manual' AND owner_id = '' AND owner_active = 1) OR\n    (ownership = 'managed' AND length(owner_id) > 0)\n  )\n)",
            "CREATE TABLE note_folder_sync_suppressions(\n  note_id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  folder_sync_id TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  PRIMARY KEY(note_id, folder_sync_id)\n)",
            "CREATE TABLE note_folders(\n  id              TEXT PRIMARY KEY,\n  parent_id       TEXT REFERENCES note_folders(id),\n  name            TEXT NOT NULL,\n  normalized_name TEXT NOT NULL,\n  path            TEXT NOT NULL,\n  normalized_path TEXT NOT NULL,\n  version         INTEGER NOT NULL DEFAULT 1 CHECK(version >= 1),\n  deleted         INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0, 1)),\n  created_at      TEXT NOT NULL,\n  modified_at     TEXT NOT NULL, sync_id TEXT,\n  CHECK(parent_id IS NULL OR parent_id <> id)\n)",
            "CREATE TABLE note_keywords(\n  note_id    TEXT    NOT NULL REFERENCES notes(id)                 ON DELETE CASCADE ON UPDATE CASCADE,\n  keyword_id INTEGER NOT NULL REFERENCES keywords(id)              ON DELETE CASCADE ON UPDATE CASCADE,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY(note_id,keyword_id)\n)",
            "CREATE TABLE note_links(\n  source_note_id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  target_note_id TEXT NOT NULL,\n  PRIMARY KEY(source_note_id, target_note_id)\n)",
            "CREATE TABLE note_organization_receipts(\n  receipt_id TEXT PRIMARY KEY,\n  note_id TEXT NOT NULL REFERENCES notes(id),\n  requested_folder_name TEXT,\n  requested_folder_sync_id TEXT,\n  requested_keywords_json TEXT NOT NULL,\n  review_id TEXT,\n  collision_ids_json TEXT NOT NULL DEFAULT '[]',\n  note_version INTEGER NOT NULL,\n  organization_version TEXT NOT NULL CHECK(\n    length(organization_version) = 64\n    AND organization_version = lower(organization_version)\n    AND organization_version NOT GLOB '*[^0-9a-f]*'\n  ),\n  state TEXT NOT NULL CHECK(state IN (\n    'pending_organization', 'placement_review'\n  )),\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  CHECK(\n    (state = 'pending_organization'\n      AND review_id IS NULL\n      AND collision_ids_json = '[]')\n    OR (state = 'placement_review'\n      AND review_id IS NOT NULL\n      AND collision_ids_json <> '[]')\n  )\n)",
            "CREATE TABLE note_sync_publication_intents(\n  intent_id TEXT PRIMARY KEY,\n  server_profile_id TEXT NOT NULL,\n  dataset_id TEXT NOT NULL,\n  note_id TEXT NOT NULL,\n  operation TEXT NOT NULL CHECK(operation IN ('create', 'update', 'delete')),\n  base_version INTEGER,\n  entity_version INTEGER NOT NULL CHECK(entity_version >= 1),\n  request_fingerprint TEXT NOT NULL CHECK(\n    length(request_fingerprint) = 64\n    AND request_fingerprint = lower(request_fingerprint)\n    AND request_fingerprint NOT GLOB '*[^0-9a-f]*'\n  ),\n  payload_json TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  outbox_client_envelope_id TEXT,\n  copied_at TEXT,\n  acknowledged_at TEXT,\n  cancelled_at TEXT,\n  UNIQUE(\n    server_profile_id, dataset_id, note_id, entity_version, operation\n  )\n)",
            "CREATE TABLE notes(\n  id            TEXT PRIMARY KEY,                     /* UUID */\n  title         TEXT NOT NULL,\n  content       TEXT NOT NULL,\n  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_modified DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted       BOOLEAN  NOT NULL DEFAULT 0,\n  client_id     TEXT     NOT NULL DEFAULT 'unknown',\n  version       INTEGER  NOT NULL DEFAULT 1\n, file_path_on_disk TEXT, relative_file_path_on_disk TEXT, sync_root_folder TEXT, last_synced_disk_file_hash TEXT, last_synced_disk_file_mtime REAL, is_externally_synced BOOLEAN NOT NULL DEFAULT 0, sync_strategy TEXT, sync_excluded BOOLEAN NOT NULL DEFAULT 0, file_extension TEXT DEFAULT '.md')",
            "CREATE VIRTUAL TABLE notes_fts\nUSING fts5(\n  title,content,\n  content='notes',\n  content_rowid='rowid'\n)",
            "CREATE TABLE 'notes_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'notes_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'notes_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'notes_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE notes_organization_adoption_reviews(\n  review_id TEXT PRIMARY KEY,\n  server_profile_id TEXT NOT NULL,\n  dataset_id TEXT NOT NULL,\n  domain TEXT NOT NULL CHECK(domain IN (\n    'notes.keyword', 'notes.keyword_collection', 'notes.folder'\n  )),\n  local_object_id TEXT NOT NULL,\n  remote_object_id TEXT,\n  collision_key TEXT NOT NULL,\n  display_name TEXT NOT NULL,\n  portable_path TEXT,\n  state TEXT NOT NULL CHECK(state IN ('open', 'resolved')),\n  resolution TEXT CHECK(resolution IN ('merge', 'rename_local', 'keep_local')),\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  resolved_at TEXT,\n  UNIQUE(server_profile_id, dataset_id, domain, local_object_id),\n  CHECK(\n    (state = 'open' AND resolution IS NULL AND resolved_at IS NULL)\n    OR (state = 'resolved' AND resolution IS NOT NULL AND resolved_at IS NOT NULL)\n  )\n)",
            "CREATE TABLE notes_organization_heads(\n  server_profile_id TEXT NOT NULL,\n  dataset_id TEXT NOT NULL,\n  domain TEXT NOT NULL CHECK(domain IN (\n    'notes.keyword', 'notes.keyword_link',\n    'notes.keyword_collection', 'notes.keyword_collection_link',\n    'notes.folder', 'notes.folder_link'\n  )),\n  object_id TEXT NOT NULL,\n  operation TEXT NOT NULL CHECK(operation IN ('upsert', 'tombstone')),\n  schema_version INTEGER NOT NULL CHECK(schema_version = 1),\n  encryption_policy TEXT NOT NULL CHECK(encryption_policy = 'server_trusted_v1'),\n  payload_json TEXT NOT NULL,\n  payload_hash TEXT NOT NULL CHECK(\n    length(payload_hash) = 64 AND payload_hash = lower(payload_hash)\n    AND payload_hash NOT GLOB '*[^0-9a-f]*'\n  ),\n  object_revision INTEGER NOT NULL CHECK(object_revision >= 1),\n  object_hash TEXT NOT NULL CHECK(\n    length(object_hash) = 64 AND object_hash = lower(object_hash)\n    AND object_hash NOT GLOB '*[^0-9a-f]*'\n  ),\n  server_cursor TEXT NOT NULL,\n  deleted INTEGER NOT NULL CHECK(deleted IN (0, 1)),\n  apply_state TEXT NOT NULL CHECK(apply_state IN ('pending', 'applied', 'blocked')),\n  applied_at TEXT,\n  updated_at TEXT NOT NULL,\n  PRIMARY KEY(server_profile_id, dataset_id, domain, object_id),\n  CHECK(\n    (operation = 'upsert' AND deleted = 0)\n    OR (operation = 'tombstone' AND deleted = 1)\n  ),\n  CHECK(\n    (apply_state = 'applied' AND applied_at IS NOT NULL)\n    OR (apply_state <> 'applied' AND applied_at IS NULL)\n  )\n)",
            "CREATE TABLE notes_organization_sync_checkpoints(\n  server_profile_id TEXT NOT NULL,\n  dataset_id TEXT NOT NULL,\n  local_state TEXT NOT NULL CHECK(local_state IN (\n    'local_only', 'initializing', 'pulling', 'adoption_review', 'ready', 'failed'\n  )),\n  server_state TEXT NOT NULL CHECK(server_state IN (\n    'unknown', 'absent', 'initializing', 'ready', 'failed', 'incompatible'\n  )),\n  bootstrap_id TEXT,\n  captured_count INTEGER NOT NULL DEFAULT 0 CHECK(captured_count >= 0),\n  expected_count INTEGER NOT NULL DEFAULT 0 CHECK(expected_count >= 0),\n  error_code TEXT,\n  pull_cursor TEXT,\n  inventory_phase TEXT NOT NULL DEFAULT 'not_started' CHECK(inventory_phase IN (\n    'not_started', 'resources', 'links', 'tombstones', 'complete'\n  )),\n  last_inventory_key TEXT,\n  updated_at TEXT NOT NULL,\n  PRIMARY KEY(server_profile_id, dataset_id),\n  CHECK(captured_count <= expected_count),\n  CHECK(\n    local_state <> 'ready'\n    OR (server_state = 'ready' AND inventory_phase = 'complete' AND error_code IS NULL)\n  )\n)",
            "CREATE TABLE notes_organization_sync_intents(\n  intent_id TEXT PRIMARY KEY,\n  intent_sequence INTEGER NOT NULL,\n  predecessor_intent_id TEXT REFERENCES notes_organization_sync_intents(intent_id),\n  server_profile_id TEXT NOT NULL,\n  dataset_id TEXT NOT NULL,\n  domain TEXT NOT NULL CHECK(domain IN (\n    'notes.keyword', 'notes.keyword_link',\n    'notes.keyword_collection', 'notes.keyword_collection_link',\n    'notes.folder', 'notes.folder_link'\n  )),\n  object_id TEXT NOT NULL,\n  operation TEXT NOT NULL CHECK(operation IN ('upsert', 'tombstone')),\n  schema_version INTEGER NOT NULL CHECK(schema_version = 1),\n  encryption_policy TEXT NOT NULL CHECK(encryption_policy = 'server_trusted_v1'),\n  payload_json TEXT NOT NULL,\n  payload_hash TEXT NOT NULL CHECK(\n    length(payload_hash) = 64 AND payload_hash = lower(payload_hash)\n    AND payload_hash NOT GLOB '*[^0-9a-f]*'\n  ),\n  routing_metadata_json TEXT NOT NULL DEFAULT '{}',\n  base_server_cursor TEXT,\n  base_object_revision INTEGER,\n  base_object_hash TEXT,\n  dependency_refs_json TEXT NOT NULL DEFAULT '[]',\n  source_version INTEGER NOT NULL CHECK(source_version >= 1),\n  created_at TEXT NOT NULL,\n  outbox_client_envelope_id TEXT,\n  copied_at TEXT,\n  acknowledged_at TEXT,\n  CHECK(\n    (base_server_cursor IS NULL) = (base_object_revision IS NULL)\n    AND (base_object_revision IS NULL) = (base_object_hash IS NULL)\n  ),\n  CHECK(outbox_client_envelope_id IS NULL OR outbox_client_envelope_id = intent_id),\n  UNIQUE(server_profile_id, dataset_id, intent_sequence),\n  UNIQUE(server_profile_id, dataset_id, domain, object_id, source_version, operation)\n)",
            "CREATE TABLE persona_visual_assets (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    pack_id INTEGER NOT NULL REFERENCES persona_visual_packs(id),\n    pack_version_id INTEGER NOT NULL,\n    asset_key TEXT NOT NULL CHECK(asset_key <> ''),\n    role TEXT NOT NULL CHECK(role <> ''),\n    storage_relpath TEXT NOT NULL\n        CHECK(storage_relpath <> ''\n              AND substr(storage_relpath, 1, 1) <> '/'\n              AND instr(storage_relpath, char(92)) = 0\n              AND instr(storage_relpath, ':') = 0\n              AND storage_relpath <> '..'\n              AND storage_relpath NOT LIKE '../%'\n              AND storage_relpath NOT LIKE '%/../%'\n              AND storage_relpath NOT LIKE '%/..'),\n    mime_type TEXT NOT NULL CHECK(mime_type <> ''),\n    bytes INTEGER NOT NULL CHECK(bytes > 0),\n    sha256 TEXT NOT NULL\n        CHECK(length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),\n    width INTEGER NOT NULL CHECK(width > 0),\n    height INTEGER NOT NULL CHECK(height > 0),\n    frame_count INTEGER CHECK(frame_count IS NULL OR frame_count > 0),\n    duration_ms INTEGER CHECK(duration_ms IS NULL OR duration_ms > 0),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY(pack_id, pack_version_id)\n        REFERENCES persona_visual_pack_versions(pack_id, id)\n)",
            "CREATE TABLE persona_visual_bindings (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    persona_id TEXT NOT NULL CHECK(persona_id <> ''),\n    persona_revision INTEGER NOT NULL CHECK(persona_revision >= 0),\n    pack_id INTEGER NOT NULL REFERENCES persona_visual_packs(id),\n    active_version_id INTEGER NOT NULL,\n    status TEXT NOT NULL DEFAULT 'active'\n        CHECK(status IN ('active', 'archived', 'deleted')),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),\n    FOREIGN KEY(pack_id, active_version_id)\n        REFERENCES persona_visual_pack_versions(pack_id, id)\n)",
            "CREATE TABLE persona_visual_pack_versions (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    pack_id INTEGER NOT NULL REFERENCES persona_visual_packs(id),\n    version_number INTEGER NOT NULL CHECK(version_number > 0),\n    renderer_type TEXT NOT NULL CHECK(renderer_type <> ''),\n    manifest_version INTEGER NOT NULL CHECK(manifest_version > 0),\n    manifest_json TEXT NOT NULL,\n    manifest_sha256 TEXT NOT NULL\n        CHECK(length(manifest_sha256) = 64\n              AND manifest_sha256 NOT GLOB '*[^0-9a-f]*'),\n    storage_relpath TEXT NOT NULL\n        CHECK(storage_relpath <> ''\n              AND substr(storage_relpath, 1, 1) <> '/'\n              AND instr(storage_relpath, char(92)) = 0\n              AND instr(storage_relpath, ':') = 0\n              AND storage_relpath <> '..'\n              AND storage_relpath NOT LIKE '../%'\n              AND storage_relpath NOT LIKE '%/../%'\n              AND storage_relpath NOT LIKE '%/..'),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    UNIQUE(pack_id, version_number),\n    UNIQUE(pack_id, id)\n)",
            "CREATE TABLE persona_visual_packs (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    title TEXT NOT NULL CHECK(title <> ''),\n    description TEXT NOT NULL DEFAULT '',\n    status TEXT NOT NULL DEFAULT 'active'\n        CHECK(status IN ('active', 'archived', 'deleted')),\n    active_version_id INTEGER,\n    source_kind TEXT NOT NULL DEFAULT 'manual' CHECK(source_kind <> ''),\n    source_context_json TEXT NOT NULL DEFAULT '{}',\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),\n    FOREIGN KEY(id, active_version_id)\n        REFERENCES persona_visual_pack_versions(pack_id, id)\n)",
            "CREATE TABLE quiz_attempts (\n    id TEXT PRIMARY KEY,\n    quiz_id TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,\n    started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    completed_at TIMESTAMP,\n    score INTEGER,\n    total_possible INTEGER NOT NULL DEFAULT 0,\n    time_spent_seconds INTEGER,\n    questions_snapshot TEXT,\n    answers TEXT,\n    client_id TEXT NOT NULL DEFAULT 'unknown'\n)",
            "CREATE TABLE quiz_questions (\n    id TEXT PRIMARY KEY,\n    quiz_id TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,\n    question_type TEXT NOT NULL,\n    question_text TEXT NOT NULL,\n    options TEXT,\n    correct_answer TEXT,\n    explanation TEXT,\n    hint TEXT,\n    hint_penalty_points INTEGER NOT NULL DEFAULT 0,\n    source_citations_json TEXT,\n    points INTEGER NOT NULL DEFAULT 1,\n    order_index INTEGER NOT NULL DEFAULT 0,\n    tags_json TEXT,\n    deleted INTEGER NOT NULL DEFAULT 0,\n    client_id TEXT NOT NULL DEFAULT 'unknown',\n    version INTEGER NOT NULL DEFAULT 1,\n    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    last_modified TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE quizzes (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    description TEXT,\n    workspace_id TEXT,\n    total_questions INTEGER NOT NULL DEFAULT 0,\n    time_limit_seconds INTEGER,\n    passing_score INTEGER,\n    deleted INTEGER NOT NULL DEFAULT 0,\n    client_id TEXT NOT NULL DEFAULT 'unknown',\n    version INTEGER NOT NULL DEFAULT 1,\n    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    last_modified TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE rag_answer_attempt_payloads(\n  profile_id TEXT NOT NULL,\n  payload_id TEXT NOT NULL\n    CHECK(length(CAST(payload_id AS BLOB)) BETWEEN 1 AND 256),\n  trace_id TEXT NOT NULL,\n  attempt_id TEXT NOT NULL\n    CHECK(length(CAST(attempt_id AS BLOB)) BETWEEN 1 AND 256),\n  redaction_state TEXT NOT NULL\n    CHECK(redaction_state IN ('available','purged')),\n  retention_class TEXT NOT NULL CHECK(length(retention_class) BETWEEN 1 AND 256),\n  answer_body TEXT\n    CHECK(answer_body IS NULL OR length(CAST(answer_body AS BLOB)) <= 1048576),\n  body_integrity_hmac TEXT\n    CHECK(body_integrity_hmac IS NULL OR length(CAST(body_integrity_hmac AS BLOB)) BETWEEN 1 AND 256),\n  created_at TEXT NOT NULL,\n  retain_until TEXT,\n  purged_at TEXT,\n  PRIMARY KEY(profile_id, payload_id),\n  UNIQUE(profile_id, trace_id, attempt_id),\n  FOREIGN KEY(profile_id, trace_id)\n    REFERENCES rag_citation_traces(profile_id, trace_id) ON DELETE CASCADE,\n  CHECK(\n    (\n      redaction_state = 'available'\n      AND answer_body IS NOT NULL\n      AND body_integrity_hmac IS NOT NULL\n      AND purged_at IS NULL\n    )\n    OR (\n      redaction_state = 'purged'\n      AND answer_body IS NULL\n      AND body_integrity_hmac IS NULL\n      AND purged_at IS NOT NULL\n    )\n  )\n)",
            "CREATE TABLE rag_artifact_owner_leases(\n  profile_id TEXT NOT NULL,\n  artifact_store_id TEXT NOT NULL\n    CHECK(length(CAST(artifact_store_id AS BLOB)) BETWEEN 1 AND 256),\n  artifact_id TEXT NOT NULL\n    CHECK(length(CAST(artifact_id AS BLOB)) BETWEEN 1 AND 256),\n  artifact_revision INTEGER NOT NULL CHECK(artifact_revision >= 0),\n  trace_id TEXT NOT NULL,\n  lease_id TEXT UNIQUE NOT NULL\n    CHECK(length(CAST(lease_id AS BLOB)) BETWEEN 1 AND 256),\n  state TEXT NOT NULL\n    CHECK(state IN ('link_pending','live','unlink_pending','released')),\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  retain_until TEXT,\n  PRIMARY KEY(profile_id, artifact_store_id, artifact_id, artifact_revision, trace_id),\n  FOREIGN KEY(profile_id, trace_id)\n    REFERENCES rag_citation_traces(profile_id, trace_id) ON DELETE RESTRICT\n)",
            "CREATE TABLE rag_artifact_owner_operations(\n  profile_id TEXT NOT NULL,\n  operation_id TEXT NOT NULL\n    CHECK(length(CAST(operation_id AS BLOB)) BETWEEN 1 AND 256),\n  artifact_store_id TEXT NOT NULL,\n  artifact_id TEXT NOT NULL,\n  artifact_revision INTEGER NOT NULL CHECK(artifact_revision >= 0),\n  trace_id TEXT NOT NULL,\n  operation_kind TEXT NOT NULL CHECK(operation_kind IN ('link','unlink')),\n  state TEXT NOT NULL CHECK(state IN ('pending','applied','acknowledged')),\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  PRIMARY KEY(profile_id, operation_id),\n  UNIQUE(\n    profile_id,\n    artifact_store_id,\n    artifact_id,\n    artifact_revision,\n    trace_id,\n    operation_kind\n  ),\n  FOREIGN KEY(profile_id, artifact_store_id, artifact_id, artifact_revision, trace_id)\n    REFERENCES rag_artifact_owner_leases(\n      profile_id,\n      artifact_store_id,\n      artifact_id,\n      artifact_revision,\n      trace_id\n    ) ON DELETE RESTRICT\n)",
            "CREATE TABLE rag_citation_traces(\n  profile_id TEXT NOT NULL\n    CHECK(length(CAST(profile_id AS BLOB)) BETWEEN 1 AND 256),\n  trace_id TEXT NOT NULL\n    CHECK(length(CAST(trace_id AS BLOB)) BETWEEN 1 AND 256),\n  schema_version INTEGER NOT NULL CHECK(schema_version = 1),\n  request_id TEXT NOT NULL\n    CHECK(length(CAST(request_id AS BLOB)) BETWEEN 1 AND 256),\n  generation_id TEXT NOT NULL\n    CHECK(length(CAST(generation_id AS BLOB)) BETWEEN 1 AND 256),\n  origin_scope_id TEXT NOT NULL\n    CHECK(length(CAST(origin_scope_id AS BLOB)) BETWEEN 1 AND 256),\n  origin TEXT NOT NULL\n    CHECK(origin IN ('local','server','imported','legacy_inferred')),\n  lifecycle TEXT NOT NULL CHECK(lifecycle = 'sealed'),\n  completeness_at_seal TEXT NOT NULL\n    CHECK(completeness_at_seal IN ('complete','partial','redacted','unavailable')),\n  selected_attempt_id TEXT NOT NULL\n    CHECK(length(CAST(selected_attempt_id AS BLOB)) BETWEEN 1 AND 256),\n  policy_version TEXT NOT NULL\n    CHECK(length(CAST(policy_version AS BLOB)) BETWEEN 1 AND 256),\n  aggregate_json TEXT NOT NULL\n    CHECK(length(CAST(aggregate_json AS BLOB)) <= 262144),\n  visibility_state TEXT NOT NULL\n    CHECK(visibility_state IN ('migrating','active')),\n  created_at TEXT NOT NULL,\n  sealed_at TEXT NOT NULL,\n  connection_authority_id TEXT\n    CHECK(connection_authority_id IS NULL OR length(CAST(connection_authority_id AS BLOB)) BETWEEN 1 AND 256),\n  tenant_id TEXT\n    CHECK(tenant_id IS NULL OR length(CAST(tenant_id AS BLOB)) BETWEEN 1 AND 256),\n  server_trace_id TEXT\n    CHECK(server_trace_id IS NULL OR length(CAST(server_trace_id AS BLOB)) BETWEEN 1 AND 256),\n  wire_schema_version TEXT\n    CHECK(wire_schema_version IS NULL OR length(CAST(wire_schema_version AS BLOB)) BETWEEN 1 AND 256),\n  import_package_fingerprint TEXT\n    CHECK(import_package_fingerprint IS NULL OR length(CAST(import_package_fingerprint AS BLOB)) BETWEEN 1 AND 256),\n  external_trace_id TEXT\n    CHECK(external_trace_id IS NULL OR length(CAST(external_trace_id AS BLOB)) BETWEEN 1 AND 256),\n  legacy_conversation_id TEXT\n    CHECK(legacy_conversation_id IS NULL OR length(CAST(legacy_conversation_id AS BLOB)) BETWEEN 1 AND 256),\n  legacy_message_id TEXT\n    CHECK(legacy_message_id IS NULL OR length(CAST(legacy_message_id AS BLOB)) BETWEEN 1 AND 256),\n  PRIMARY KEY(profile_id, trace_id),\n  CHECK(\n    (\n      origin = 'local'\n      AND origin_scope_id = profile_id\n      AND connection_authority_id IS NULL\n      AND tenant_id IS NULL\n      AND server_trace_id IS NULL\n      AND wire_schema_version IS NULL\n      AND import_package_fingerprint IS NULL\n      AND external_trace_id IS NULL\n      AND legacy_conversation_id IS NULL\n      AND legacy_message_id IS NULL\n    )\n    OR (\n      origin = 'server'\n      AND connection_authority_id IS NOT NULL\n      AND server_trace_id IS NOT NULL\n      AND wire_schema_version IS NOT NULL\n      AND origin_scope_id = COALESCE(tenant_id, 'authority-root')\n      AND import_package_fingerprint IS NULL\n      AND external_trace_id IS NULL\n      AND legacy_conversation_id IS NULL\n      AND legacy_message_id IS NULL\n    )\n    OR (\n      origin = 'imported'\n      AND origin_scope_id = import_package_fingerprint\n      AND import_package_fingerprint IS NOT NULL\n      AND external_trace_id IS NOT NULL\n      AND connection_authority_id IS NULL\n      AND tenant_id IS NULL\n      AND server_trace_id IS NULL\n      AND wire_schema_version IS NULL\n      AND legacy_conversation_id IS NULL\n      AND legacy_message_id IS NULL\n    )\n    OR (\n      origin = 'legacy_inferred'\n      AND origin_scope_id = profile_id\n      AND legacy_conversation_id IS NOT NULL\n      AND legacy_message_id IS NOT NULL\n      AND connection_authority_id IS NULL\n      AND tenant_id IS NULL\n      AND server_trace_id IS NULL\n      AND wire_schema_version IS NULL\n      AND import_package_fingerprint IS NULL\n      AND external_trace_id IS NULL\n    )\n  )\n)",
            "CREATE TABLE rag_evidence_runs(\n  profile_id TEXT NOT NULL,\n  trace_id TEXT NOT NULL,\n  run_id TEXT NOT NULL\n    CHECK(length(CAST(run_id AS BLOB)) BETWEEN 1 AND 256),\n  run_ordinal INTEGER NOT NULL CHECK(run_ordinal >= 0),\n  stage TEXT NOT NULL CHECK(length(stage) BETWEEN 1 AND 256),\n  redaction_state TEXT NOT NULL\n    CHECK(redaction_state IN ('available','redacted','purged')),\n  run_payload_json TEXT\n    CHECK(run_payload_json IS NULL OR length(CAST(run_payload_json AS BLOB)) <= 4194304),\n  started_at TEXT NOT NULL,\n  ended_at TEXT,\n  purged_at TEXT,\n  PRIMARY KEY(profile_id, trace_id, run_id),\n  UNIQUE(profile_id, trace_id, run_ordinal),\n  FOREIGN KEY(profile_id, trace_id)\n    REFERENCES rag_citation_traces(profile_id, trace_id) ON DELETE CASCADE,\n  CHECK(\n    (redaction_state = 'available' AND run_payload_json IS NOT NULL AND purged_at IS NULL)\n    OR (redaction_state = 'redacted' AND run_payload_json IS NULL)\n    OR (redaction_state = 'purged' AND run_payload_json IS NULL AND purged_at IS NOT NULL)\n  )\n)",
            "CREATE TABLE rag_evidence_snapshots(\n  profile_id TEXT NOT NULL\n    CHECK(length(CAST(profile_id AS BLOB)) BETWEEN 1 AND 256),\n  payload_id TEXT NOT NULL\n    CHECK(length(CAST(payload_id AS BLOB)) BETWEEN 1 AND 256),\n  governance_scope_id TEXT NOT NULL\n    CHECK(length(CAST(governance_scope_id AS BLOB)) BETWEEN 1 AND 256),\n  authority_id TEXT NOT NULL\n    CHECK(length(CAST(authority_id AS BLOB)) BETWEEN 1 AND 256),\n  confidentiality_policy_id TEXT NOT NULL\n    CHECK(length(CAST(confidentiality_policy_id AS BLOB)) BETWEEN 1 AND 256),\n  revocation_scope_id TEXT NOT NULL\n    CHECK(length(CAST(revocation_scope_id AS BLOB)) BETWEEN 1 AND 256),\n  origin_namespace TEXT NOT NULL\n    CHECK(length(CAST(origin_namespace AS BLOB)) BETWEEN 1 AND 256),\n  origin_payload_id TEXT NOT NULL\n    CHECK(length(CAST(origin_payload_id AS BLOB)) BETWEEN 1 AND 256),\n  storage_mode TEXT NOT NULL\n    CHECK(storage_mode IN ('embedded','server_reference','ephemeral','redacted')),\n  redaction_state TEXT NOT NULL\n    CHECK(redaction_state IN ('available','redacted','purged')),\n  retention_class TEXT NOT NULL CHECK(length(retention_class) BETWEEN 1 AND 256),\n  snapshot_text TEXT\n    CHECK(snapshot_text IS NULL OR length(CAST(snapshot_text AS BLOB)) <= 65536),\n  title TEXT,\n  source_identity_json TEXT\n    CHECK(source_identity_json IS NULL OR length(CAST(source_identity_json AS BLOB)) <= 16384),\n  locator_json TEXT\n    CHECK(locator_json IS NULL OR length(CAST(locator_json AS BLOB)) <= 16384),\n  lineage_json TEXT\n    CHECK(lineage_json IS NULL OR length(CAST(lineage_json AS BLOB)) <= 16384),\n  transformations_json TEXT\n    CHECK(transformations_json IS NULL OR length(CAST(transformations_json AS BLOB)) <= 16384),\n  content_hash TEXT\n    CHECK(content_hash IS NULL OR length(CAST(content_hash AS BLOB)) BETWEEN 1 AND 256),\n  comparison_fingerprint TEXT\n    CHECK(comparison_fingerprint IS NULL OR length(CAST(comparison_fingerprint AS BLOB)) BETWEEN 1 AND 256),\n  created_at TEXT NOT NULL,\n  retain_until TEXT,\n  purged_at TEXT,\n  PRIMARY KEY(profile_id, payload_id),\n  CHECK(\n    (redaction_state = 'available' AND purged_at IS NULL)\n    OR (redaction_state = 'redacted')\n    OR (\n      redaction_state = 'purged'\n      AND snapshot_text IS NULL\n      AND title IS NULL\n      AND source_identity_json IS NULL\n      AND locator_json IS NULL\n      AND lineage_json IS NULL\n      AND transformations_json IS NULL\n      AND content_hash IS NULL\n      AND comparison_fingerprint IS NULL\n      AND purged_at IS NOT NULL\n    )\n  )\n)",
            "CREATE TABLE rag_identity_context(\n  context_name TEXT PRIMARY KEY NOT NULL CHECK(context_name = 'default'),\n  profile_id TEXT UNIQUE NOT NULL\n    CHECK(length(CAST(profile_id AS BLOB)) BETWEEN 1 AND 256),\n  local_authority_id TEXT UNIQUE NOT NULL\n    CHECK(length(CAST(local_authority_id AS BLOB)) BETWEEN 1 AND 256),\n  fingerprint_key_id TEXT UNIQUE NOT NULL\n    CHECK(length(CAST(fingerprint_key_id AS BLOB)) BETWEEN 1 AND 256),\n  created_at TEXT NOT NULL\n)",
            "CREATE TABLE rag_legacy_migration_journal(\n  profile_id TEXT NOT NULL\n    CHECK(length(CAST(profile_id AS BLOB)) BETWEEN 1 AND 256),\n  conversation_id TEXT NOT NULL,\n  source_fingerprint TEXT NOT NULL\n    CHECK(length(CAST(source_fingerprint AS BLOB)) BETWEEN 1 AND 256),\n  state TEXT NOT NULL\n    CHECK(state IN ('pending','running','complete','failed','diverged')),\n  attempt_count INTEGER NOT NULL CHECK(attempt_count >= 0),\n  started_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  next_message_cursor TEXT\n    CHECK(next_message_cursor IS NULL OR length(CAST(next_message_cursor AS BLOB)) BETWEEN 1 AND 256),\n  error_code TEXT CHECK(error_code IS NULL OR length(error_code) <= 256),\n  completed_at TEXT,\n  PRIMARY KEY(profile_id, conversation_id),\n  FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE\n)",
            "CREATE TABLE rag_message_trace_owners(\n  profile_id TEXT NOT NULL,\n  message_id TEXT NOT NULL,\n  message_revision INTEGER NOT NULL CHECK(message_revision >= 0),\n  trace_id TEXT NOT NULL,\n  state TEXT NOT NULL CHECK(state IN ('active','body_mismatch','deleted')),\n  body_fingerprint TEXT NOT NULL\n    CHECK(length(CAST(body_fingerprint AS BLOB)) BETWEEN 1 AND 256),\n  idempotency_key TEXT NOT NULL\n    CHECK(length(CAST(idempotency_key AS BLOB)) BETWEEN 1 AND 256),\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  PRIMARY KEY(profile_id, message_id, message_revision, trace_id),\n  UNIQUE(profile_id, idempotency_key),\n  FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE,\n  FOREIGN KEY(profile_id, trace_id)\n    REFERENCES rag_citation_traces(profile_id, trace_id) ON DELETE RESTRICT\n)",
            "CREATE TABLE rag_payload_tombstones(\n  profile_id TEXT NOT NULL\n    CHECK(length(CAST(profile_id AS BLOB)) BETWEEN 1 AND 256),\n  origin_namespace TEXT NOT NULL\n    CHECK(length(CAST(origin_namespace AS BLOB)) BETWEEN 1 AND 256),\n  origin_payload_id TEXT NOT NULL\n    CHECK(length(CAST(origin_payload_id AS BLOB)) BETWEEN 1 AND 256),\n  revocation_scope_id TEXT NOT NULL\n    CHECK(length(CAST(revocation_scope_id AS BLOB)) BETWEEN 1 AND 256),\n  reason_code TEXT NOT NULL CHECK(length(reason_code) BETWEEN 1 AND 256),\n  policy_version TEXT NOT NULL\n    CHECK(length(CAST(policy_version AS BLOB)) BETWEEN 1 AND 256),\n  revoked_at TEXT NOT NULL,\n  retain_until TEXT NOT NULL,\n  PRIMARY KEY(profile_id, origin_namespace, origin_payload_id)\n)",
            "CREATE TABLE rag_source_observations(\n  profile_id TEXT NOT NULL,\n  trace_id TEXT NOT NULL,\n  prompt_set_id TEXT NOT NULL\n    CHECK(length(CAST(prompt_set_id AS BLOB)) BETWEEN 1 AND 256),\n  evidence_ordinal INTEGER NOT NULL CHECK(evidence_ordinal >= 0),\n  snapshot_payload_id TEXT NOT NULL,\n  resolver_kind TEXT NOT NULL\n    CHECK(length(CAST(resolver_kind AS BLOB)) BETWEEN 1 AND 256),\n  resolver_version TEXT NOT NULL\n    CHECK(length(CAST(resolver_version AS BLOB)) BETWEEN 1 AND 256),\n  availability TEXT NOT NULL CHECK(length(availability) BETWEEN 1 AND 256),\n  permission_state TEXT NOT NULL CHECK(length(permission_state) BETWEEN 1 AND 256),\n  content_state TEXT NOT NULL CHECK(length(content_state) BETWEEN 1 AND 256),\n  location_state TEXT NOT NULL CHECK(length(location_state) BETWEEN 1 AND 256),\n  capabilities_json TEXT NOT NULL\n    CHECK(length(CAST(capabilities_json AS BLOB)) <= 8192),\n  request_nonce TEXT NOT NULL\n    CHECK(length(CAST(request_nonce AS BLOB)) BETWEEN 1 AND 256),\n  observed_at TEXT NOT NULL,\n  error_code TEXT CHECK(error_code IS NULL OR length(error_code) <= 256),\n  PRIMARY KEY(\n    profile_id,\n    trace_id,\n    prompt_set_id,\n    evidence_ordinal,\n    snapshot_payload_id,\n    resolver_kind,\n    resolver_version\n  ),\n  FOREIGN KEY(profile_id, trace_id)\n    REFERENCES rag_citation_traces(profile_id, trace_id) ON DELETE CASCADE,\n  FOREIGN KEY(profile_id, snapshot_payload_id)\n    REFERENCES rag_evidence_snapshots(profile_id, payload_id) ON DELETE CASCADE\n)",
            "CREATE TABLE rag_trace_evidence_refs(\n  profile_id TEXT NOT NULL,\n  trace_id TEXT NOT NULL,\n  prompt_set_id TEXT NOT NULL\n    CHECK(length(CAST(prompt_set_id AS BLOB)) BETWEEN 1 AND 256),\n  evidence_ordinal INTEGER NOT NULL CHECK(evidence_ordinal >= 0),\n  run_id TEXT NOT NULL,\n  snapshot_payload_id TEXT NOT NULL,\n  marker_ordinal INTEGER NOT NULL CHECK(marker_ordinal >= 0),\n  storage_mode TEXT NOT NULL\n    CHECK(storage_mode IN ('embedded','server_reference','ephemeral','redacted')),\n  PRIMARY KEY(profile_id, trace_id, prompt_set_id, evidence_ordinal),\n  UNIQUE(profile_id, trace_id, prompt_set_id, marker_ordinal),\n  FOREIGN KEY(profile_id, trace_id)\n    REFERENCES rag_citation_traces(profile_id, trace_id) ON DELETE CASCADE,\n  FOREIGN KEY(profile_id, trace_id, run_id)\n    REFERENCES rag_evidence_runs(profile_id, trace_id, run_id) ON DELETE CASCADE,\n  FOREIGN KEY(profile_id, snapshot_payload_id)\n    REFERENCES rag_evidence_snapshots(profile_id, payload_id) ON DELETE RESTRICT\n)",
            "CREATE TABLE research_quick_note_owner_proofs(\n  note_id     TEXT PRIMARY KEY NOT NULL\n              REFERENCES notes(id) ON DELETE CASCADE ON UPDATE CASCADE,\n  owner_proof TEXT NOT NULL CHECK (\n      length(owner_proof) = 64\n      AND owner_proof = lower(owner_proof)\n      AND owner_proof NOT GLOB '*[^0-9a-f]*'\n  ),\n  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE review_history (\n    id TEXT PRIMARY KEY,\n    flashcard_id TEXT REFERENCES flashcards(id) ON DELETE CASCADE,\n    reviewed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    rating INTEGER NOT NULL,  -- 0-5 (Again, Hard, Good, Easy, etc.)\n    time_taken INTEGER,       -- Seconds to answer\n    interval_before INTEGER,  -- Previous interval\n    interval_after INTEGER,   -- New interval\n    ease_before REAL,\n    ease_after REAL\n)",
            "CREATE TABLE sqlite_sequence(name,seq)",
            "CREATE TABLE study_sessions (\n    id TEXT PRIMARY KEY,\n    entity_type TEXT NOT NULL,  -- topic, flashcard_deck, mindmap\n    entity_id TEXT NOT NULL,\n    started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    ended_at TIMESTAMP,\n    duration INTEGER,  -- Seconds\n    cards_reviewed INTEGER DEFAULT 0,\n    topics_completed INTEGER DEFAULT 0,\n    metadata TEXT     -- JSON for session details\n)",
            "CREATE TABLE sync_conflicts(\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id TEXT NOT NULL REFERENCES sync_sessions(session_id),\n  note_id TEXT REFERENCES notes(id),\n  file_path TEXT NOT NULL,\n  conflict_type TEXT NOT NULL CHECK(conflict_type IN ('both_changed', 'deleted_on_disk', 'deleted_in_db')),\n  db_content_hash TEXT,\n  disk_content_hash TEXT,\n  db_modified_time DATETIME,\n  disk_modified_time REAL,\n  resolution TEXT CHECK(resolution IN ('use_db', 'use_disk', 'merge', 'skip', NULL)),\n  resolved_at DATETIME,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n, losing_side TEXT, losing_content TEXT, preserved_file_path TEXT)",
            "CREATE TABLE sync_log(\n  change_id   INTEGER  PRIMARY KEY AUTOINCREMENT,\n  entity      TEXT     NOT NULL,\n  entity_id   TEXT     NOT NULL,\n  operation   TEXT     NOT NULL CHECK(operation IN('create','update','delete')),\n  timestamp   DATETIME NOT NULL,\n  client_id   TEXT     NOT NULL,\n  version     INTEGER  NOT NULL,\n  payload     TEXT     NOT NULL          /* JSON blob */\n)",
            "CREATE TABLE sync_sessions(\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id TEXT UNIQUE NOT NULL,  -- UUID for the sync session\n  sync_root_folder TEXT NOT NULL,\n  sync_direction TEXT NOT NULL CHECK(sync_direction IN ('disk_to_db', 'db_to_disk', 'bidirectional')),\n  conflict_resolution TEXT NOT NULL CHECK(conflict_resolution IN ('ask', 'disk_wins', 'db_wins', 'newer_wins')),\n  started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  completed_at DATETIME,\n  status TEXT NOT NULL CHECK(status IN ('running', 'completed', 'failed', 'cancelled')),\n  total_files INTEGER DEFAULT 0,\n  processed_files INTEGER DEFAULT 0,\n  conflicts_found INTEGER DEFAULT 0,\n  errors_count INTEGER DEFAULT 0,\n  client_id TEXT NOT NULL,\n  summary TEXT  -- JSON summary of the sync operation\n)",
            "CREATE TABLE topics (\n    id TEXT PRIMARY KEY,\n    path_id TEXT REFERENCES learning_paths(id) ON DELETE CASCADE,\n    parent_id TEXT REFERENCES topics(id) ON DELETE CASCADE,\n    title TEXT NOT NULL,\n    content TEXT,\n    topic_order INTEGER DEFAULT 0,\n    status TEXT DEFAULT 'not_started',  -- not_started, in_progress, completed\n    progress REAL DEFAULT 0.0,  -- 0.0 to 1.0\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    created_by TEXT NOT NULL,\n    last_modified_by TEXT NOT NULL,\n    version INTEGER DEFAULT 1,\n    is_deleted INTEGER DEFAULT 0,\n    metadata TEXT     -- JSON for additional data\n)",
            "CREATE VIRTUAL TABLE topics_fts USING fts5(\n    title, content, content=topics, content_rowid=rowid\n)",
            "CREATE TABLE 'topics_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'topics_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'topics_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'topics_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE transcript_annotations (\n    annotation_id TEXT PRIMARY KEY,\n    conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,\n    row_key TEXT NOT NULL,\n    message_id TEXT,\n    quote_text TEXT NOT NULL,\n    comment TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    deleted BOOLEAN NOT NULL DEFAULT 0\n)",
            "CREATE TABLE visual_identity_assets (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    owner_user_id INTEGER NOT NULL,\n    pack_id INTEGER REFERENCES visual_identity_packs(id),\n    pack_version_id INTEGER NOT NULL REFERENCES visual_identity_pack_versions(id),\n    expression_key TEXT NOT NULL,\n    original_expression_key TEXT NOT NULL DEFAULT '',\n    display_label TEXT NOT NULL DEFAULT '',\n    source_filename TEXT NOT NULL,\n    storage_relpath TEXT NOT NULL,\n    content_type TEXT NOT NULL,\n    bytes INTEGER NOT NULL CHECK(bytes > 0),\n    sha256 TEXT NOT NULL,\n    width INTEGER NOT NULL CHECK(width > 0),\n    height INTEGER NOT NULL CHECK(height > 0),\n    source_context_json TEXT NOT NULL DEFAULT '{}',\n    is_animated INTEGER NOT NULL DEFAULT 0 CHECK(is_animated IN (0, 1)),\n    frame_count INTEGER,\n    duration_ms INTEGER,\n    preview_relpath TEXT,\n    deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0, 1)),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE TABLE visual_identity_bindings (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    owner_user_id INTEGER NOT NULL,\n    actor_kind TEXT NOT NULL CHECK(actor_kind IN ('character', 'persona')),\n    actor_id TEXT NOT NULL,\n    pack_id INTEGER NOT NULL REFERENCES visual_identity_packs(id),\n    active_version_id INTEGER NOT NULL REFERENCES visual_identity_pack_versions(id),\n    status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active', 'deleted')),\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    version INTEGER NOT NULL DEFAULT 1\n)",
            "CREATE TABLE visual_identity_pack_versions (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    pack_id INTEGER NOT NULL REFERENCES visual_identity_packs(id),\n    owner_user_id INTEGER NOT NULL,\n    version_number INTEGER NOT NULL,\n    default_expression_key TEXT NOT NULL DEFAULT 'neutral',\n    manifest_json TEXT NOT NULL,\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    UNIQUE(pack_id, version_number)\n)",
            "CREATE TABLE visual_identity_packs (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    owner_user_id INTEGER NOT NULL,\n    title TEXT NOT NULL,\n    description TEXT NOT NULL DEFAULT '',\n    status TEXT NOT NULL DEFAULT 'active'\n        CHECK(status IN ('active', 'archived', 'deleted')),\n    active_version_id INTEGER REFERENCES visual_identity_pack_versions(id),\n    default_expression_key TEXT NOT NULL DEFAULT 'neutral',\n    source_kind TEXT NOT NULL DEFAULT 'manual',\n    source_context_json TEXT NOT NULL DEFAULT '{}',\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    version INTEGER NOT NULL DEFAULT 1\n)",
            "CREATE TABLE world_book_entries(\n  id              INTEGER  PRIMARY KEY AUTOINCREMENT,\n  world_book_id   INTEGER  NOT NULL REFERENCES world_books(id) ON DELETE CASCADE,\n  keys            TEXT     NOT NULL, -- JSON array of keywords\n  content         TEXT     NOT NULL,\n  enabled         BOOLEAN  DEFAULT 1,\n  position        TEXT     DEFAULT 'before_char', -- before_char, after_char, at_start, at_end\n  insertion_order INTEGER  DEFAULT 0,\n  priority        INTEGER  DEFAULT 0,\n  selective       BOOLEAN  DEFAULT 0,\n  secondary_keys  TEXT,    -- JSON array of secondary keywords\n  case_sensitive  BOOLEAN  DEFAULT 0,\n  regex           BOOLEAN  DEFAULT 0,\n  extensions      TEXT,    -- JSON for future extensibility\n  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_modified   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n)",
            "CREATE VIRTUAL TABLE world_book_entries_fts\nUSING fts5(\n  keys, content,\n  content='world_book_entries',\n  content_rowid='id'\n)",
            "CREATE TABLE 'world_book_entries_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'world_book_entries_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'world_book_entries_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'world_book_entries_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TABLE world_books(\n  id              INTEGER  PRIMARY KEY AUTOINCREMENT,\n  name            TEXT     UNIQUE NOT NULL,\n  description     TEXT,\n  scan_depth      INTEGER  DEFAULT 3,\n  token_budget    INTEGER  DEFAULT 500,\n  recursive_scanning BOOLEAN DEFAULT 0,\n  enabled         BOOLEAN  NOT NULL DEFAULT 1,\n  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_modified   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  deleted         BOOLEAN  NOT NULL DEFAULT 0,\n  client_id       TEXT     NOT NULL DEFAULT 'unknown',\n  version         INTEGER  NOT NULL DEFAULT 1\n)",
            "CREATE VIRTUAL TABLE world_books_fts\nUSING fts5(\n  name, description,\n  content='world_books',\n  content_rowid='id'\n)",
            "CREATE TABLE 'world_books_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID",
            "CREATE TABLE 'world_books_fts_data'(id INTEGER PRIMARY KEY, block BLOB)",
            "CREATE TABLE 'world_books_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)",
            "CREATE TABLE 'world_books_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID",
            "CREATE TRIGGER agent_lessons_seed_state_monotonic_update\nBEFORE UPDATE OF scope_mode, state ON agent_lessons_seed_state\nWHEN (OLD.state = 'seeded' AND NEW.state <> 'seeded')\n OR (\n   OLD.scope_mode = 'synchronized'\n   AND (\n     NEW.scope_mode <> 'synchronized'\n     OR (OLD.state = 'not_seeded' AND NEW.state = 'unknown')\n   )\n )\nBEGIN\n  SELECT RAISE(ABORT, 'agent_lessons_seed_state cannot regress');\nEND",
            "CREATE TRIGGER canvas_documents_ownership_immutable\nBEFORE UPDATE OF id, conversation_id, created_at ON canvas_documents\nWHEN\n  OLD.id IS NOT NEW.id\n  OR OLD.conversation_id IS NOT NEW.conversation_id\n  OR OLD.created_at IS NOT NEW.created_at\nBEGIN\n  SELECT RAISE(ABORT, 'canvas document ownership is immutable');\nEND",
            "CREATE TRIGGER canvas_origin_message_owner_guard\nBEFORE UPDATE OF conversation_id ON messages\nWHEN OLD.conversation_id IS NOT NEW.conversation_id\n  AND EXISTS (\n    SELECT 1\n      FROM canvas_revisions AS revision\n      JOIN canvas_documents AS document\n        ON document.id = revision.canvas_id\n     WHERE revision.origin_message_id = OLD.id\n       AND document.conversation_id IS NOT NEW.conversation_id\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'canvas revision origin owner mismatch');\nEND",
            "CREATE TRIGGER canvas_revisions_no_delete\nBEFORE DELETE ON canvas_revisions\nWHEN canvas_revision_delete_authorized(OLD.canvas_id) <> 1\nBEGIN\n  SELECT RAISE(ABORT, 'canvas revision deletion authorization required');\nEND",
            "CREATE TRIGGER canvas_revisions_no_update\nBEFORE UPDATE ON canvas_revisions\nBEGIN\n  SELECT RAISE(ABORT, 'canvas revisions are immutable');\nEND",
            "CREATE TRIGGER canvas_revisions_origin_owner_guard\nBEFORE INSERT ON canvas_revisions\nWHEN NOT EXISTS (\n  SELECT 1\n    FROM canvas_documents AS document\n    JOIN messages AS message\n      ON message.id = NEW.origin_message_id\n   WHERE document.id = NEW.canvas_id\n     AND message.conversation_id = document.conversation_id\n)\nBEGIN\n  SELECT RAISE(ABORT, 'canvas revision origin owner mismatch');\nEND",
            "CREATE TRIGGER canvas_revisions_parent_guard\nBEFORE INSERT ON canvas_revisions\nWHEN NEW.parent_revision_id IS NOT NULL AND NOT EXISTS (\n  SELECT 1\n    FROM canvas_revisions AS parent\n   WHERE parent.id = NEW.parent_revision_id\n     AND parent.canvas_id = NEW.canvas_id\n     AND parent.sequence < NEW.sequence\n)\nBEGIN\n  SELECT RAISE(ABORT, 'canvas revision parent mismatch');\nEND",
            "CREATE TRIGGER character_cards_ad\nAFTER DELETE ON character_cards BEGIN\n  INSERT INTO character_cards_fts(character_cards_fts,rowid,\n                                  name,description,personality,scenario,system_prompt)\n  VALUES('delete',old.id,old.name,old.description,old.personality,old.scenario,old.system_prompt);\nEND",
            "CREATE TRIGGER character_cards_ai\nAFTER INSERT ON character_cards BEGIN\n  INSERT INTO character_cards_fts(rowid,name,description,personality,scenario,system_prompt)\n  SELECT new.id,new.name,new.description,new.personality,new.scenario,new.system_prompt\n  WHERE new.deleted = 0;\nEND",
