            "CREATE TRIGGER chat_dictionaries_au\nAFTER UPDATE ON chat_dictionaries BEGIN\n  INSERT INTO chat_dictionaries_fts(chat_dictionaries_fts, rowid, name, description, content)\n  SELECT 'delete', OLD.id, OLD.name, OLD.description, OLD.content\n  WHERE OLD.deleted = 0;\n\n  INSERT INTO chat_dictionaries_fts(rowid, name, description, content)\n  SELECT NEW.id, NEW.name, NEW.description, NEW.content\n  WHERE NEW.deleted = 0;\nEND",
            "CREATE TRIGGER chat_dictionaries_sync_create\nAFTER INSERT ON chat_dictionaries BEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('chat_dictionaries', CAST(NEW.id AS TEXT), 'create', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'file_path', NEW.file_path, 'strategy', NEW.strategy, 'max_tokens', NEW.max_tokens,\n                     'enabled', NEW.enabled, 'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
            "CREATE TRIGGER chat_dictionaries_sync_delete\nAFTER UPDATE ON chat_dictionaries\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('chat_dictionaries', CAST(NEW.id AS TEXT), 'delete', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'deleted', NEW.deleted, 'last_modified', NEW.last_modified,\n                     'version', NEW.version, 'client_id', NEW.client_id));\nEND",
            "CREATE TRIGGER chat_dictionaries_sync_undelete\nAFTER UPDATE ON chat_dictionaries\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('chat_dictionaries', CAST(NEW.id AS TEXT), 'update', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'file_path', NEW.file_path, 'strategy', NEW.strategy, 'max_tokens', NEW.max_tokens,\n                     'enabled', NEW.enabled, 'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
            "CREATE TRIGGER chat_dictionaries_sync_update\nAFTER UPDATE ON chat_dictionaries\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.name IS NOT NEW.name OR\n     OLD.description IS NOT NEW.description OR\n     OLD.file_path IS NOT NEW.file_path OR\n     OLD.content IS NOT NEW.content OR\n     OLD.entries_json IS NOT NEW.entries_json OR\n     OLD.strategy IS NOT NEW.strategy OR\n     OLD.max_tokens IS NOT NEW.max_tokens OR\n     OLD.enabled IS NOT NEW.enabled OR\n     OLD.last_modified IS NOT NEW.last_modified OR\n     OLD.version IS NOT NEW.version)\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('chat_dictionaries', CAST(NEW.id AS TEXT), 'update', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'file_path', NEW.file_path, 'strategy', NEW.strategy, 'max_tokens', NEW.max_tokens,\n                     'enabled', NEW.enabled, 'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
            "CREATE TRIGGER chat_dictionaries_update_timestamp\nAFTER UPDATE ON chat_dictionaries\nBEGIN\n  UPDATE chat_dictionaries SET last_modified = CURRENT_TIMESTAMP WHERE id = NEW.id;\nEND",
            "CREATE TRIGGER console_trace_artifacts_no_delete\nBEFORE DELETE ON console_trace_artifacts\nWHEN console_trace_gc_delete_authorized('console_trace_artifacts') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_artifacts_no_update\nBEFORE UPDATE ON console_trace_artifacts BEGIN\n  SELECT RAISE(ABORT, 'console_trace_artifacts is append-only');\nEND",
            "CREATE TRIGGER console_trace_call_boundary_source_guard\nBEFORE INSERT ON console_trace_events\nWHEN NEW.event_type = 'call_boundary' AND NEW.semantic_revision_id IS NOT NULL\n AND NOT EXISTS (\n   SELECT 1 FROM console_trace_calls AS call\n   JOIN console_trace_owners AS owner ON owner.owner_id = call.owner_id\n   JOIN console_trace_semantic_revisions AS revision\n     ON revision.revision_id = NEW.semantic_revision_id\n   WHERE call.call_id = NEW.call_id AND call.segment_id = NEW.segment_id\n     AND revision.source_message_id = call.turn_id\n     AND revision.source_conversation_id = owner.conversation_id\n )\nBEGIN\n  SELECT RAISE(ABORT, 'trace call boundary source does not own its turn');\nEND",
            "CREATE TRIGGER console_trace_calls_binding_guard\nBEFORE UPDATE ON console_trace_calls\nWHEN NEW.surface_node_id IS NOT NULL AND (\n  OLD.surface_node_id IS NOT NEW.surface_node_id OR\n  OLD.request_header_id IS NOT NEW.request_header_id OR\n  OLD.provider_name IS NOT NEW.provider_name OR\n  OLD.model_name IS NOT NEW.model_name OR\n  OLD.route_identity IS NOT NEW.route_identity\n) AND NOT EXISTS (\n  WITH RECURSIVE\n  inherited_chain(node_id, predecessor_node_id) AS (\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_segments AS segment\n      JOIN console_trace_surface_nodes AS node\n        ON node.node_id = segment.inherited_surface_head_id\n     WHERE segment.segment_id = NEW.segment_id\n    UNION ALL\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n      JOIN inherited_chain AS successor\n        ON successor.predecessor_node_id = node.node_id\n  ),\n  call_surface_chain(node_id, predecessor_node_id) AS (\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n     WHERE node.node_id = NEW.surface_node_id\n    UNION ALL\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n      JOIN call_surface_chain AS successor\n        ON successor.predecessor_node_id = node.node_id\n  )\n  SELECT 1\n    FROM console_trace_segments AS segment\n    JOIN console_trace_surface_nodes AS surface\n      ON surface.node_id = NEW.surface_node_id\n    JOIN console_trace_request_headers AS header\n      ON header.header_id = NEW.request_header_id\n   WHERE segment.segment_id = NEW.segment_id\n     AND header.provider_name = NEW.provider_name\n     AND header.model_name = NEW.model_name\n     AND header.route_identity = NEW.route_identity\n     AND (\n       (segment.parent_segment_id IS NULL AND\n        surface.segment_id = NEW.segment_id) OR\n       (segment.parent_segment_id IS NOT NULL AND (\n         (surface.segment_id = NEW.segment_id AND EXISTS (\n           SELECT 1 FROM call_surface_chain\n            WHERE node_id = segment.inherited_surface_head_id\n         )) OR\n         EXISTS (\n           SELECT 1 FROM inherited_chain\n            WHERE node_id = surface.node_id\n         )\n       ))\n     )\n)\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'call binding must match reachable surface and immutable request header'\n  );\nEND",
            "CREATE TRIGGER console_trace_calls_immutable_guard\nBEFORE UPDATE ON console_trace_calls\nWHEN\n  OLD.call_id IS NOT NEW.call_id OR\n  OLD.owner_id IS NOT NEW.owner_id OR\n  OLD.segment_id IS NOT NEW.segment_id OR\n  OLD.turn_id IS NOT NEW.turn_id OR\n  OLD.run_id IS NOT NEW.run_id OR\n  OLD.call_sequence IS NOT NEW.call_sequence OR\n  OLD.idempotency_key IS NOT NEW.idempotency_key OR\n  OLD.policy_id IS NOT NEW.policy_id OR\n  OLD.created_at IS NOT NEW.created_at\nBEGIN\n  SELECT RAISE(ABORT, 'provider call ownership and identity are immutable');\nEND",
            "CREATE TRIGGER console_trace_calls_insert_reserved\nBEFORE INSERT ON console_trace_calls\nWHEN NOT (\n  (\n    NEW.reservation_provenance = 'crash_durable_reserved' AND\n    NEW.import_reason_code IS NULL AND\n    NEW.state = 'reserved' AND\n    NEW.surface_node_id IS NULL AND NEW.request_header_id IS NULL AND\n    NEW.provider_name IS NULL AND NEW.model_name IS NULL AND\n    NEW.route_identity IS NULL AND NEW.dispatch_started_at IS NULL AND\n    NEW.response_started_at IS NULL AND NEW.settled_at IS NULL AND\n    NEW.provider_inactive_at IS NULL AND NEW.outcome IS NULL AND\n    NEW.usage_json IS NULL AND NEW.integrity_state = 'pending' AND\n    NEW.omission_reason_code IS NULL\n  ) OR (\n    NEW.reservation_provenance = 'post_dispatch_promoted' AND\n    NEW.import_reason_code = 'provisional_voice_promoted' AND\n    NEW.state IN ('complete', 'stopped', 'error', 'interrupted') AND\n    NEW.surface_node_id IS NOT NULL AND NEW.request_header_id IS NOT NULL AND\n    NEW.provider_name IS NOT NULL AND NEW.model_name IS NOT NULL AND\n    NEW.route_identity IS NOT NULL AND NEW.dispatch_started_at IS NOT NULL AND\n    NEW.settled_at IS NOT NULL AND NEW.provider_inactive_at IS NULL AND\n    NEW.outcome = NEW.state AND\n    NEW.integrity_state = 'complete' AND NEW.omission_reason_code IS NULL AND\n    console_voice_trace_import_authorized(NEW.call_id) = 1\n  )\n)\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'provider call reservation provenance or terminal import authorization is invalid'\n  );\nEND",
            "CREATE TRIGGER console_trace_calls_lifecycle_guard\nBEFORE UPDATE ON console_trace_calls\nWHEN NEW.state IS NOT OLD.state AND NOT (\n  (OLD.state = 'reserved' AND NEW.state IN ('not_dispatched', 'dispatch_started')) OR\n  (OLD.state = 'dispatch_started' AND (\n    NEW.state IN ('response_started', 'dispatch_unknown', 'abandoned') OR\n    (NEW.state = 'error' AND NEW.response_started_at IS NULL)\n  )) OR\n  (OLD.state = 'response_started' AND NEW.state IN (\n    'complete', 'stopped', 'error', 'interrupted'\n  ))\n)\nBEGIN\n  SELECT RAISE(ABORT, 'invalid provider call lifecycle transition');\nEND",
            "CREATE TRIGGER console_trace_calls_no_delete\nBEFORE DELETE ON console_trace_calls\nWHEN console_trace_gc_delete_authorized('console_trace_calls') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_calls_open_root_epoch\nAFTER UPDATE OF state ON console_trace_calls\nWHEN (\n  OLD.state IN ('reserved', 'dispatch_started', 'response_started')\n) <> (\n  NEW.state IN ('reserved', 'dispatch_started', 'response_started')\n)\nBEGIN\n  UPDATE console_trace_graph_epoch\n     SET epoch = epoch + 1, updated_at = CURRENT_TIMESTAMP\n   WHERE singleton_id = 1;\nEND",
            "CREATE TRIGGER console_trace_calls_owner_lineage\nBEFORE INSERT ON console_trace_calls\nWHEN NOT EXISTS (\n  WITH RECURSIVE segment_ancestry(segment_id, depth) AS (\n    SELECT NEW.segment_id, 0\n    UNION ALL\n    SELECT segment.parent_segment_id, child.depth + 1\n      FROM console_trace_segments AS segment\n      JOIN segment_ancestry AS child\n        ON child.segment_id = segment.segment_id\n     WHERE segment.parent_segment_id IS NOT NULL\n  ),\n  effective_owner AS (\n    SELECT owner.owner_id, owner.attached\n      FROM segment_ancestry AS owned\n      JOIN console_trace_owners AS owner\n        ON owner.root_segment_id = owned.segment_id\n     ORDER BY owned.depth\n     LIMIT 1\n  )\n  SELECT 1\n    FROM effective_owner AS owner\n   WHERE owner.owner_id = NEW.owner_id\n     AND owner.attached = 1\n)\nBEGIN\n  SELECT RAISE(ABORT, 'provider call must use the active effective owner');\nEND",
            "CREATE TRIGGER console_trace_calls_provenance_update_guard\nBEFORE UPDATE ON console_trace_calls\nWHEN\n  OLD.reservation_provenance IS NOT NEW.reservation_provenance OR\n  OLD.import_reason_code IS NOT NEW.import_reason_code\nBEGIN\n  SELECT RAISE(ABORT, 'provider call provenance is immutable');\nEND",
            "CREATE TRIGGER console_trace_calls_set_once_guard\nBEFORE UPDATE ON console_trace_calls\nWHEN\n  (OLD.surface_node_id IS NOT NULL AND OLD.surface_node_id IS NOT NEW.surface_node_id) OR\n  (OLD.request_header_id IS NOT NULL AND OLD.request_header_id IS NOT NEW.request_header_id) OR\n  (OLD.provider_name IS NOT NULL AND OLD.provider_name IS NOT NEW.provider_name) OR\n  (OLD.model_name IS NOT NULL AND OLD.model_name IS NOT NEW.model_name) OR\n  (OLD.route_identity IS NOT NULL AND OLD.route_identity IS NOT NEW.route_identity) OR\n  (OLD.dispatch_started_at IS NOT NULL AND OLD.dispatch_started_at IS NOT NEW.dispatch_started_at) OR\n  (OLD.response_started_at IS NOT NULL AND OLD.response_started_at IS NOT NEW.response_started_at) OR\n  (OLD.settled_at IS NOT NULL AND OLD.settled_at IS NOT NEW.settled_at) OR\n  (OLD.provider_inactive_at IS NOT NULL AND OLD.provider_inactive_at IS NOT NEW.provider_inactive_at) OR\n  (OLD.outcome IS NOT NULL AND OLD.outcome IS NOT NEW.outcome) OR\n  (OLD.usage_json IS NOT NULL AND OLD.usage_json IS NOT NEW.usage_json) OR\n  (OLD.omission_reason_code IS NOT NULL AND\n   OLD.omission_reason_code IS NOT NEW.omission_reason_code) OR\n  (OLD.integrity_state IS NOT NEW.integrity_state AND NOT (\n    OLD.integrity_state = 'pending' AND\n    NEW.integrity_state IN ('complete', 'incomplete')\n  ))\nBEGIN\n  SELECT RAISE(ABORT, 'provider call settlement fields are set-once');\nEND",
            "CREATE TRIGGER console_trace_calls_terminal_guard\nBEFORE UPDATE ON console_trace_calls\nWHEN OLD.state IN (\n  'not_dispatched', 'dispatch_unknown', 'complete', 'stopped', 'error',\n  'interrupted', 'abandoned'\n) AND (\n  OLD.state IS NOT NEW.state OR\n  OLD.surface_node_id IS NOT NEW.surface_node_id OR\n  OLD.request_header_id IS NOT NEW.request_header_id OR\n  OLD.provider_name IS NOT NEW.provider_name OR\n  OLD.model_name IS NOT NEW.model_name OR\n  OLD.route_identity IS NOT NEW.route_identity OR\n  OLD.dispatch_started_at IS NOT NEW.dispatch_started_at OR\n  OLD.response_started_at IS NOT NEW.response_started_at OR\n  OLD.settled_at IS NOT NEW.settled_at OR\n  OLD.provider_inactive_at IS NOT NEW.provider_inactive_at OR\n  OLD.outcome IS NOT NEW.outcome OR\n  OLD.usage_json IS NOT NEW.usage_json OR\n  OLD.integrity_state IS NOT NEW.integrity_state OR\n  OLD.omission_reason_code IS NOT NEW.omission_reason_code\n)\nBEGIN\n  SELECT RAISE(ABORT, 'terminal provider call settlement is immutable');\nEND",
            "CREATE TRIGGER console_trace_compaction_state_immutable_key\nBEFORE UPDATE ON console_trace_compaction_state\nWHEN OLD.singleton_id IS NOT NEW.singleton_id\nBEGIN\n  SELECT RAISE(ABORT, 'trace compaction singleton identity is immutable');\nEND",
            "CREATE TRIGGER console_trace_compaction_state_no_delete\nBEFORE DELETE ON console_trace_compaction_state BEGIN\n  SELECT RAISE(ABORT, 'console_trace_compaction_state deletion prohibited');\nEND",
            "CREATE TRIGGER console_trace_conversations_detach_owner\nBEFORE DELETE ON conversations\nBEGIN\n  UPDATE console_trace_owners\n     SET conversation_id = NULL,\n         attached = 0,\n         detached_at = CURRENT_TIMESTAMP\n   WHERE conversation_id = OLD.id\n     AND attached = 1;\n  UPDATE console_trace_graph_epoch\n     SET epoch = epoch + 1\n   WHERE singleton_id = 1\n     AND changes() > 0;\nEND",
            "CREATE TRIGGER console_trace_events_append_order\nBEFORE INSERT ON console_trace_events\nWHEN EXISTS (\n  SELECT 1\n    FROM console_trace_events AS existing\n   WHERE existing.segment_id = NEW.segment_id\n     AND existing.sequence >= NEW.sequence\n)\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'trace event sequence must preserve per-segment append order'\n  );\nEND",
            "CREATE TRIGGER console_trace_events_lineage_guard\nBEFORE INSERT ON console_trace_events\nWHEN\n  (NEW.surface_node_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1\n      FROM console_trace_surface_nodes AS surface\n     WHERE surface.node_id = NEW.surface_node_id\n       AND surface.segment_id = NEW.segment_id\n  )) OR\n  (NEW.surface_replacement_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1\n      FROM console_trace_surface_replacements AS replacement\n     WHERE replacement.replacement_id = NEW.surface_replacement_id\n       AND replacement.segment_id = NEW.segment_id\n  )) OR\n  (NEW.call_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1\n      FROM console_trace_calls AS call\n     WHERE call.call_id = NEW.call_id\n       AND call.segment_id = NEW.segment_id\n  )) OR\n  (NEW.request_header_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1\n      FROM console_trace_calls AS call\n     WHERE call.call_id = NEW.call_id\n       AND call.segment_id = NEW.segment_id\n       AND call.request_header_id = NEW.request_header_id\n  ))\nBEGIN\n  SELECT RAISE(ABORT, 'trace event ownership lineage is inconsistent');\nEND",
            "CREATE TRIGGER console_trace_events_no_delete\nBEFORE DELETE ON console_trace_events\nWHEN console_trace_gc_delete_authorized('console_trace_events') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_events_no_update\nBEFORE UPDATE ON console_trace_events BEGIN\n  SELECT RAISE(ABORT, 'console_trace_events is append-only');\nEND",
            "CREATE TRIGGER console_trace_events_owner_guard\nBEFORE INSERT ON console_trace_events\nWHEN NOT EXISTS (\n  WITH RECURSIVE segment_ancestry(segment_id, depth) AS (\n    SELECT NEW.segment_id, 0\n    UNION ALL\n    SELECT segment.parent_segment_id, child.depth + 1\n      FROM console_trace_segments AS segment\n      JOIN segment_ancestry AS child\n        ON child.segment_id = segment.segment_id\n     WHERE segment.parent_segment_id IS NOT NULL\n  ),\n  effective_owner AS (\n    SELECT owner.conversation_id, owner.attached\n      FROM segment_ancestry AS owned\n      JOIN console_trace_owners AS owner\n        ON owner.root_segment_id = owned.segment_id\n     ORDER BY owned.depth\n     LIMIT 1\n  )\n  SELECT 1\n    FROM effective_owner AS owner\n   WHERE owner.attached = 1\n     AND (\n       NEW.semantic_revision_id IS NULL OR EXISTS (\n         SELECT 1\n           FROM console_trace_semantic_revisions AS revision\n          WHERE revision.revision_id = NEW.semantic_revision_id\n            AND revision.source_conversation_id = owner.conversation_id\n       )\n     )\n)\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'trace event requires one active effective owner and matching revision domain'\n  );\nEND",
            "CREATE TRIGGER console_trace_events_shape_guard\nBEFORE INSERT ON console_trace_events\nWHEN NOT (\n  (NEW.event_type = 'call_boundary' AND\n   NEW.turn_id IS NULL AND NEW.call_id IS NOT NULL AND\n   NEW.surface_node_id IS NULL AND NEW.surface_replacement_id IS NULL AND\n   NEW.request_header_id IS NULL AND NEW.artifact_id IS NULL AND\n   NEW.omission_reason_code IS NULL) OR\n  (NEW.event_type = 'turn_boundary' AND\n   NEW.turn_id IS NOT NULL AND\n   NEW.call_id IS NULL AND NEW.surface_node_id IS NULL AND\n   NEW.surface_replacement_id IS NULL AND NEW.request_header_id IS NULL AND\n   NEW.semantic_revision_id IS NULL AND NEW.artifact_id IS NULL AND\n   NEW.omission_reason_code IS NULL) OR\n  (NEW.event_type IN ('call_outcome', 'usage') AND\n   NEW.turn_id IS NULL AND NEW.call_id IS NOT NULL AND\n   NEW.surface_node_id IS NULL AND NEW.surface_replacement_id IS NULL AND\n   NEW.request_header_id IS NULL AND NEW.semantic_revision_id IS NULL AND\n   NEW.artifact_id IS NULL AND NEW.omission_reason_code IS NULL) OR\n  (NEW.event_type = 'surface_append' AND\n   NEW.turn_id IS NULL AND NEW.call_id IS NULL AND\n   NEW.surface_node_id IS NOT NULL AND NEW.surface_replacement_id IS NULL AND\n   NEW.request_header_id IS NULL AND NEW.semantic_revision_id IS NULL AND\n   NEW.artifact_id IS NULL AND NEW.omission_reason_code IS NULL) OR\n  (NEW.event_type = 'surface_replace' AND\n   NEW.turn_id IS NULL AND NEW.call_id IS NULL AND\n   NEW.surface_node_id IS NULL AND NEW.surface_replacement_id IS NOT NULL AND\n   NEW.request_header_id IS NULL AND NEW.semantic_revision_id IS NULL AND\n   NEW.artifact_id IS NULL AND NEW.omission_reason_code IS NULL) OR\n  (NEW.event_type IN ('tool_call', 'tool_result') AND\n   NEW.turn_id IS NULL AND NEW.call_id IS NOT NULL AND\n   NEW.surface_node_id IS NULL AND NEW.surface_replacement_id IS NULL AND\n   NEW.request_header_id IS NULL AND\n   ((NEW.semantic_revision_id IS NOT NULL) +\n    (NEW.artifact_id IS NOT NULL) +\n    (NEW.omission_reason_code IS NOT NULL)) = 1) OR\n  (NEW.event_type IN (\n     'request_header_selection', 'provider_route_selection'\n   ) AND\n   NEW.turn_id IS NULL AND NEW.call_id IS NOT NULL AND\n   NEW.surface_node_id IS NULL AND NEW.surface_replacement_id IS NULL AND\n   NEW.request_header_id IS NOT NULL AND NEW.semantic_revision_id IS NULL AND\n   NEW.artifact_id IS NULL AND NEW.omission_reason_code IS NULL) OR\n  (NEW.event_type = 'response_selection' AND\n   NEW.turn_id IS NULL AND NEW.call_id IS NOT NULL AND\n   NEW.surface_node_id IS NULL AND NEW.surface_replacement_id IS NULL AND\n   NEW.request_header_id IS NULL AND NEW.omission_reason_code IS NULL AND\n   ((NEW.semantic_revision_id IS NOT NULL) +\n    (NEW.artifact_id IS NOT NULL)) = 1) OR\n  (NEW.event_type = 'gap' AND\n   NEW.turn_id IS NULL AND NEW.call_id IS NULL AND\n   NEW.surface_node_id IS NULL AND NEW.surface_replacement_id IS NULL AND\n   NEW.request_header_id IS NULL AND NEW.semantic_revision_id IS NULL AND\n   NEW.artifact_id IS NULL AND NEW.omission_reason_code IS NOT NULL)\n)\nBEGIN\n  SELECT RAISE(ABORT, 'invalid trace event reference shape');\nEND",
            "CREATE TRIGGER console_trace_graph_epoch_monotonic\nBEFORE UPDATE ON console_trace_graph_epoch\nWHEN OLD.singleton_id IS NOT NEW.singleton_id OR NEW.epoch <> OLD.epoch + 1\nBEGIN\n  SELECT RAISE(ABORT, 'trace graph epoch must advance by exactly one');\nEND",
            "CREATE TRIGGER console_trace_graph_epoch_no_delete\nBEFORE DELETE ON console_trace_graph_epoch BEGIN\n  SELECT RAISE(ABORT, 'console_trace_graph_epoch deletion prohibited');\nEND",
            "CREATE TRIGGER console_trace_header_components_no_delete\nBEFORE DELETE ON console_trace_header_components\nWHEN console_trace_gc_delete_authorized('console_trace_header_components') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_header_components_no_update\nBEFORE UPDATE ON console_trace_header_components BEGIN\n  SELECT RAISE(ABORT, 'console_trace_header_components is append-only');\nEND",
            "CREATE TRIGGER console_trace_maintenance_state_immutable_key\nBEFORE UPDATE ON console_trace_maintenance_state\nWHEN OLD.singleton_id IS NOT NEW.singleton_id\nBEGIN\n  SELECT RAISE(ABORT, 'trace maintenance singleton identity is immutable');\nEND",
            "CREATE TRIGGER console_trace_maintenance_state_no_delete\nBEFORE DELETE ON console_trace_maintenance_state BEGIN\n  SELECT RAISE(ABORT, 'console_trace_maintenance_state deletion prohibited');\nEND",
            "CREATE TRIGGER console_trace_migration_root_epoch\nAFTER UPDATE OF status ON console_trace_migration_state\nWHEN (OLD.status <> 'logical_complete') <> (NEW.status <> 'logical_complete')\nBEGIN\n  UPDATE console_trace_graph_epoch\n     SET epoch = epoch + 1, updated_at = CURRENT_TIMESTAMP\n   WHERE singleton_id = 1;\nEND",
            "CREATE TRIGGER console_trace_migration_state_immutable_key\nBEFORE UPDATE ON console_trace_migration_state\nWHEN OLD.migration_name IS NOT NEW.migration_name\nBEGIN\n  SELECT RAISE(ABORT, 'trace migration identity is immutable');\nEND",
            "CREATE TRIGGER console_trace_migration_state_no_delete\nBEFORE DELETE ON console_trace_migration_state BEGIN\n  SELECT RAISE(ABORT, 'console_trace_migration_state deletion prohibited');\nEND",
            "CREATE TRIGGER console_trace_owners_active_prefix_guard\nBEFORE INSERT ON console_trace_owners\nWHEN EXISTS (\n  WITH RECURSIVE segment_ancestry(segment_id, depth) AS (\n    SELECT root.parent_segment_id, 0\n      FROM console_trace_segments AS root\n     WHERE root.segment_id = NEW.root_segment_id\n       AND root.parent_segment_id IS NOT NULL\n    UNION ALL\n    SELECT segment.parent_segment_id, child.depth + 1\n      FROM console_trace_segments AS segment\n      JOIN segment_ancestry AS child\n        ON child.segment_id = segment.segment_id\n     WHERE segment.parent_segment_id IS NOT NULL\n  ),\n  effective_owner AS (\n    SELECT owner.attached\n      FROM segment_ancestry AS owned\n      JOIN console_trace_owners AS owner\n        ON owner.root_segment_id = owned.segment_id\n     ORDER BY owned.depth\n     LIMIT 1\n  )\n  SELECT 1 FROM effective_owner WHERE attached = 0\n)\nBEGIN\n  SELECT RAISE(ABORT, 'trace owner cannot revive a detached owner prefix');\nEND",
            "CREATE TRIGGER console_trace_owners_detach_only\nBEFORE UPDATE ON console_trace_owners\nWHEN\n  OLD.owner_id IS NOT NEW.owner_id OR\n  OLD.root_segment_id IS NOT NEW.root_segment_id OR\n  OLD.created_at IS NOT NEW.created_at OR\n  NOT (\n    OLD.attached = 1 AND NEW.attached = 0 AND\n    OLD.conversation_id IS NOT NULL AND NEW.conversation_id IS NULL AND\n    OLD.detached_at IS NULL AND NEW.detached_at IS NOT NULL\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'trace owner updates are limited to one-way detach');\nEND",
            "CREATE TRIGGER console_trace_owners_empty_root_guard\nBEFORE INSERT ON console_trace_owners\nWHEN\n  EXISTS (\n    SELECT 1 FROM console_trace_surface_nodes\n     WHERE segment_id = NEW.root_segment_id\n  ) OR\n  EXISTS (\n    SELECT 1 FROM console_trace_surface_replacements\n     WHERE segment_id = NEW.root_segment_id\n  ) OR\n  EXISTS (\n    SELECT 1 FROM console_trace_calls\n     WHERE segment_id = NEW.root_segment_id\n  ) OR\n  EXISTS (\n    SELECT 1 FROM console_trace_events\n     WHERE segment_id = NEW.root_segment_id\n  ) OR\n  EXISTS (\n    SELECT 1 FROM console_trace_segments\n     WHERE parent_segment_id = NEW.root_segment_id\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'trace owner must attach to a distinct empty root segment');\nEND",
            "CREATE TRIGGER console_trace_owners_no_delete\nBEFORE DELETE ON console_trace_owners\nWHEN console_trace_gc_delete_authorized('console_trace_owners') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_policies_no_delete\nBEFORE DELETE ON console_trace_policies\nWHEN console_trace_gc_delete_authorized('console_trace_policies') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_policies_no_update\nBEFORE UPDATE ON console_trace_policies BEGIN\n  SELECT RAISE(ABORT, 'console_trace_policies is append-only');\nEND",
            "CREATE TRIGGER console_trace_redaction_spans_no_delete\nBEFORE DELETE ON console_trace_redaction_spans\nWHEN console_trace_gc_delete_authorized('console_trace_redaction_spans') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_redaction_spans_no_update\nBEFORE UPDATE ON console_trace_redaction_spans BEGIN\n  SELECT RAISE(ABORT, 'console_trace_redaction_spans is append-only');\nEND",
            "CREATE TRIGGER console_trace_request_headers_no_delete\nBEFORE DELETE ON console_trace_request_headers\nWHEN console_trace_gc_delete_authorized('console_trace_request_headers') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_request_headers_no_update\nBEFORE UPDATE ON console_trace_request_headers BEGIN\n  SELECT RAISE(ABORT, 'console_trace_request_headers is append-only');\nEND",
            "CREATE TRIGGER console_trace_response_links_no_delete\nBEFORE DELETE ON console_trace_response_links\nWHEN console_trace_gc_delete_authorized('console_trace_response_links') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_response_links_no_update\nBEFORE UPDATE ON console_trace_response_links BEGIN\n  SELECT RAISE(ABORT, 'console_trace_response_links is append-only');\nEND",
            "CREATE TRIGGER console_trace_response_links_owner_guard\nBEFORE INSERT ON console_trace_response_links\nWHEN NOT EXISTS (\n  WITH RECURSIVE segment_ancestry(segment_id, depth) AS (\n    SELECT call.segment_id, 0\n      FROM console_trace_calls AS call\n     WHERE call.call_id = NEW.call_id\n    UNION ALL\n    SELECT segment.parent_segment_id, child.depth + 1\n      FROM console_trace_segments AS segment\n      JOIN segment_ancestry AS child\n        ON child.segment_id = segment.segment_id\n     WHERE segment.parent_segment_id IS NOT NULL\n  ),\n  effective_owner AS (\n    SELECT owner.owner_id, owner.conversation_id, owner.attached\n      FROM segment_ancestry AS owned\n      JOIN console_trace_owners AS owner\n        ON owner.root_segment_id = owned.segment_id\n     ORDER BY owned.depth\n     LIMIT 1\n  )\n  SELECT 1\n    FROM console_trace_calls AS call\n    JOIN effective_owner AS owner\n      ON owner.owner_id = call.owner_id\n   WHERE call.call_id = NEW.call_id\n     AND owner.attached = 1\n     AND (\n       NEW.semantic_revision_id IS NULL OR EXISTS (\n         SELECT 1\n           FROM console_trace_semantic_revisions AS revision\n          WHERE revision.revision_id = NEW.semantic_revision_id\n            AND revision.source_conversation_id = owner.conversation_id\n       )\n     )\n)\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'response link requires one active effective owner and matching revision domain'\n  );\nEND",
            "CREATE TRIGGER console_trace_retention_roots_delete_epoch\nAFTER DELETE ON console_trace_retention_roots\nWHEN julianday(OLD.retain_until) > julianday('now')\nBEGIN\n  UPDATE console_trace_graph_epoch\n     SET epoch = epoch + 1, updated_at = CURRENT_TIMESTAMP\n   WHERE singleton_id = 1;\nEND",
            "CREATE TRIGGER console_trace_retention_roots_insert_epoch\nAFTER INSERT ON console_trace_retention_roots\nBEGIN\n  UPDATE console_trace_graph_epoch\n     SET epoch = epoch + 1, updated_at = CURRENT_TIMESTAMP\n   WHERE singleton_id = 1;\nEND",
            "CREATE TRIGGER console_trace_retention_roots_no_delete\nBEFORE DELETE ON console_trace_retention_roots\nWHEN console_trace_gc_delete_authorized('console_trace_retention_roots') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_retention_roots_no_update\nBEFORE UPDATE ON console_trace_retention_roots\nBEGIN SELECT RAISE(ABORT, 'console_trace_retention_roots is immutable'); END",
            "CREATE TRIGGER console_trace_revision_bindings_no_delete\nBEFORE DELETE ON console_trace_revision_bindings\nWHEN console_trace_gc_delete_authorized('console_trace_revision_bindings') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_revision_bindings_no_update\nBEFORE UPDATE ON console_trace_revision_bindings BEGIN\n  SELECT RAISE(ABORT, 'console_trace_revision_bindings is append-only');\nEND",
            "CREATE TRIGGER console_trace_segments_inherited_surface\nBEFORE INSERT ON console_trace_segments\nWHEN NEW.parent_segment_id IS NOT NULL AND NOT EXISTS (\n  WITH RECURSIVE\n  parent_inherited_chain(node_id, predecessor_node_id) AS (\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_segments AS parent\n      JOIN console_trace_surface_nodes AS node\n        ON node.node_id = parent.inherited_surface_head_id\n     WHERE parent.segment_id = NEW.parent_segment_id\n    UNION ALL\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n      JOIN parent_inherited_chain AS successor\n        ON successor.predecessor_node_id = node.node_id\n  ),\n  last_surface_event(head_id) AS (\n    SELECT CASE event.event_type\n             WHEN 'surface_append' THEN event.surface_node_id\n             ELSE replacement.replacement_node_id\n           END\n      FROM console_trace_events AS event\n      LEFT JOIN console_trace_surface_replacements AS replacement\n        ON replacement.replacement_id = event.surface_replacement_id\n     WHERE event.segment_id = NEW.parent_segment_id\n       AND event.sequence <= NEW.inherited_through_sequence\n       AND event.event_type IN ('surface_append', 'surface_replace')\n     ORDER BY event.sequence DESC\n     LIMIT 1\n  ),\n  expected_surface(head_id) AS (\n    SELECT head_id FROM last_surface_event\n    UNION ALL\n    SELECT parent.inherited_surface_head_id\n      FROM console_trace_segments AS parent\n     WHERE parent.segment_id = NEW.parent_segment_id\n       AND NOT EXISTS (SELECT 1 FROM last_surface_event)\n  )\n  SELECT 1\n    FROM console_trace_segments AS parent\n    JOIN expected_surface AS expected\n      ON expected.head_id = NEW.inherited_surface_head_id\n    JOIN console_trace_surface_nodes AS head\n      ON head.node_id = expected.head_id\n   WHERE parent.segment_id = NEW.parent_segment_id\n     AND (\n       head.segment_id = parent.segment_id OR\n       EXISTS (\n         SELECT 1 FROM parent_inherited_chain\n          WHERE node_id = head.node_id\n       )\n     )\n)\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'inherited surface head must match the parent surface at the event boundary'\n  );\nEND",
            "CREATE TRIGGER console_trace_segments_no_delete\nBEFORE DELETE ON console_trace_segments\nWHEN console_trace_gc_delete_authorized('console_trace_segments') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_segments_no_update\nBEFORE UPDATE ON console_trace_segments BEGIN\n  SELECT RAISE(ABORT, 'console_trace_segments is append-only');\nEND",
            "CREATE TRIGGER console_trace_segments_parent_owner_guard\nBEFORE INSERT ON console_trace_segments\nWHEN NEW.parent_segment_id IS NOT NULL AND EXISTS (\n  WITH RECURSIVE segment_ancestry(segment_id, depth) AS (\n    SELECT NEW.parent_segment_id, 0\n    UNION ALL\n    SELECT segment.parent_segment_id, child.depth + 1\n      FROM console_trace_segments AS segment\n      JOIN segment_ancestry AS child\n        ON child.segment_id = segment.segment_id\n     WHERE segment.parent_segment_id IS NOT NULL\n  ),\n  effective_owner AS (\n    SELECT owner.attached\n      FROM segment_ancestry AS owned\n      JOIN console_trace_owners AS owner\n        ON owner.root_segment_id = owned.segment_id\n     ORDER BY owned.depth\n     LIMIT 1\n  )\n  SELECT 1 FROM effective_owner WHERE attached = 0\n)\nBEGIN\n  SELECT RAISE(ABORT, 'child segment cannot extend a detached owner prefix');\nEND",
            "CREATE TRIGGER console_trace_semantic_revisions_lineage\nBEFORE INSERT ON console_trace_semantic_revisions\nWHEN\n  (NEW.live_message_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1\n      FROM messages AS source\n     WHERE source.id = NEW.live_message_id\n       AND source.id = NEW.source_message_id\n       AND source.conversation_id = NEW.source_conversation_id\n  )) OR\n  (NEW.predecessor_revision_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1\n      FROM console_trace_semantic_revisions AS predecessor\n     WHERE predecessor.revision_id = NEW.predecessor_revision_id\n       AND predecessor.source_conversation_id = NEW.source_conversation_id\n       AND predecessor.source_message_id = NEW.source_message_id\n       AND predecessor.revision_sequence = NEW.revision_sequence - 1\n  ))\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'semantic revision locator or predecessor lineage is inconsistent'\n  );\nEND",
            "CREATE TRIGGER console_trace_semantic_revisions_locator_only\nBEFORE UPDATE ON console_trace_semantic_revisions\nWHEN\n  OLD.revision_id IS NOT NEW.revision_id OR\n  OLD.source_conversation_id IS NOT NEW.source_conversation_id OR\n  OLD.source_message_id IS NOT NEW.source_message_id OR\n  OLD.revision_sequence IS NOT NEW.revision_sequence OR\n  OLD.normalized_role IS NOT NEW.normalized_role OR\n  OLD.content_kind IS NOT NEW.content_kind OR\n  OLD.creation_reason IS NOT NEW.creation_reason OR\n  OLD.predecessor_revision_id IS NOT NEW.predecessor_revision_id OR\n  OLD.created_at IS NOT NEW.created_at OR\n  NOT (\n    OLD.live_message_id IS NOT NULL AND NEW.live_message_id IS NULL AND\n    OLD.live_locator_retired_at IS NULL AND\n    NEW.live_locator_retired_at IS NOT NULL\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'semantic revision updates are limited to locator retirement');\nEND",
            "CREATE TRIGGER console_trace_semantic_revisions_no_delete\nBEFORE DELETE ON console_trace_semantic_revisions\nWHEN console_trace_gc_delete_authorized('console_trace_semantic_revisions') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_semantic_revisions_retirement_guard\nBEFORE UPDATE OF live_message_id, live_locator_retired_at\nON console_trace_semantic_revisions\nWHEN OLD.live_message_id IS NOT NULL AND (\n  NEW.live_message_id IS NOT NULL OR\n  NEW.live_locator_retired_at IS NULL OR\n  console_semantic_mutation_authorized(OLD.live_message_id, 'locator_retire') <> 1\n)\nBEGIN\n  SELECT RAISE(ABORT, 'semantic mutation authorization required for locator retirement');\nEND",
            "CREATE TRIGGER console_trace_surface_nodes_contiguous\nBEFORE INSERT ON console_trace_surface_nodes\nWHEN\n  (NEW.predecessor_node_id IS NULL AND (\n    NEW.sequence <> 0 OR EXISTS (\n      SELECT 1 FROM console_trace_segments AS segment\n       WHERE segment.segment_id = NEW.segment_id\n         AND segment.parent_segment_id IS NOT NULL\n    )\n  )) OR\n  (NEW.predecessor_node_id IS NOT NULL AND NOT EXISTS (\n    SELECT 1\n      FROM console_trace_surface_nodes AS predecessor\n      JOIN console_trace_segments AS segment\n        ON segment.segment_id = NEW.segment_id\n     WHERE predecessor.node_id = NEW.predecessor_node_id\n       AND predecessor.sequence = NEW.sequence - 1\n       AND (\n         (segment.parent_segment_id IS NULL AND\n          predecessor.segment_id = NEW.segment_id) OR\n         (segment.parent_segment_id IS NOT NULL AND (\n           predecessor.segment_id = NEW.segment_id OR\n           predecessor.node_id = segment.inherited_surface_head_id\n         ))\n       )\n  ))\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'surface node predecessor must be contiguous and within segment lineage'\n  );\nEND",
            "CREATE TRIGGER console_trace_surface_nodes_no_delete\nBEFORE DELETE ON console_trace_surface_nodes\nWHEN console_trace_gc_delete_authorized('console_trace_surface_nodes') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_surface_nodes_no_update\nBEFORE UPDATE ON console_trace_surface_nodes BEGIN\n  SELECT RAISE(ABORT, 'console_trace_surface_nodes is append-only');\nEND",
            "CREATE TRIGGER console_trace_surface_nodes_owner_guard\nBEFORE INSERT ON console_trace_surface_nodes\nWHEN NOT EXISTS (\n  WITH RECURSIVE segment_ancestry(segment_id, depth) AS (\n    SELECT NEW.segment_id, 0\n    UNION ALL\n    SELECT segment.parent_segment_id, child.depth + 1\n      FROM console_trace_segments AS segment\n      JOIN segment_ancestry AS child\n        ON child.segment_id = segment.segment_id\n     WHERE segment.parent_segment_id IS NOT NULL\n  ),\n  effective_owner AS (\n    SELECT owner.conversation_id, owner.attached\n      FROM segment_ancestry AS owned\n      JOIN console_trace_owners AS owner\n        ON owner.root_segment_id = owned.segment_id\n     ORDER BY owned.depth\n     LIMIT 1\n  )\n  SELECT 1\n    FROM effective_owner AS owner\n   WHERE owner.attached = 1\n     AND (\n       NEW.semantic_revision_id IS NULL OR EXISTS (\n         SELECT 1\n           FROM console_trace_semantic_revisions AS revision\n          WHERE revision.revision_id = NEW.semantic_revision_id\n            AND revision.source_conversation_id = owner.conversation_id\n       )\n     )\n)\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'surface node requires one active effective owner and matching revision domain'\n  );\nEND",
            "CREATE TRIGGER console_trace_surface_replacements_lineage\nBEFORE INSERT ON console_trace_surface_replacements\nWHEN NOT EXISTS (\n  WITH RECURSIVE\n  inherited_chain(node_id, predecessor_node_id) AS (\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_segments AS segment\n      JOIN console_trace_surface_nodes AS node\n        ON node.node_id = segment.inherited_surface_head_id\n     WHERE segment.segment_id = NEW.segment_id\n    UNION ALL\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n      JOIN inherited_chain AS successor\n        ON successor.predecessor_node_id = node.node_id\n  ),\n  predecessor_chain(node_id, predecessor_node_id) AS (\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n     WHERE node.node_id = NEW.predecessor_head_id\n    UNION ALL\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n      JOIN predecessor_chain AS successor\n        ON successor.predecessor_node_id = node.node_id\n  ),\n  replacement_chain(node_id, predecessor_node_id) AS (\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n     WHERE node.node_id = NEW.replacement_node_id\n    UNION ALL\n    SELECT node.node_id, node.predecessor_node_id\n      FROM console_trace_surface_nodes AS node\n      JOIN replacement_chain AS successor\n        ON successor.predecessor_node_id = node.node_id\n  )\n  SELECT 1\n    FROM console_trace_segments AS segment\n    JOIN console_trace_surface_nodes AS predecessor_head\n      ON predecessor_head.node_id = NEW.predecessor_head_id\n    JOIN console_trace_surface_nodes AS replacement\n      ON replacement.node_id = NEW.replacement_node_id\n   WHERE segment.segment_id = NEW.segment_id\n     AND (\n       (segment.parent_segment_id IS NULL AND\n        predecessor_head.segment_id = NEW.segment_id) OR\n       (segment.parent_segment_id IS NOT NULL AND (\n         (predecessor_head.segment_id = NEW.segment_id AND EXISTS (\n           SELECT 1 FROM predecessor_chain\n            WHERE node_id = segment.inherited_surface_head_id\n         )) OR\n         EXISTS (\n           SELECT 1 FROM inherited_chain\n            WHERE node_id = predecessor_head.node_id\n         )\n       ))\n     )\n     AND replacement.segment_id = NEW.segment_id\n     AND replacement.node_id <> predecessor_head.node_id\n     AND EXISTS (\n       SELECT 1 FROM predecessor_chain\n        WHERE node_id = NEW.start_node_id\n     )\n     AND EXISTS (\n       SELECT 1 FROM predecessor_chain\n        WHERE node_id = NEW.end_node_id\n     )\n     AND EXISTS (\n       SELECT 1 FROM replacement_chain\n        WHERE node_id = NEW.predecessor_head_id\n     )\n)\nBEGIN\n  SELECT RAISE(ABORT, 'surface replacement references must remain within lineage');\nEND",
            "CREATE TRIGGER console_trace_surface_replacements_no_delete\nBEFORE DELETE ON console_trace_surface_replacements\nWHEN console_trace_gc_delete_authorized('console_trace_surface_replacements') <> 1\nBEGIN SELECT RAISE(ABORT, 'trace GC deletion authorization required'); END",
            "CREATE TRIGGER console_trace_surface_replacements_no_update\nBEFORE UPDATE ON console_trace_surface_replacements BEGIN\n  SELECT RAISE(ABORT, 'console_trace_surface_replacements is append-only');\nEND",
            "CREATE TRIGGER console_trace_surface_replacements_owner_guard\nBEFORE INSERT ON console_trace_surface_replacements\nWHEN NOT EXISTS (\n  WITH RECURSIVE segment_ancestry(segment_id, depth) AS (\n    SELECT NEW.segment_id, 0\n    UNION ALL\n    SELECT segment.parent_segment_id, child.depth + 1\n      FROM console_trace_segments AS segment\n      JOIN segment_ancestry AS child\n        ON child.segment_id = segment.segment_id\n     WHERE segment.parent_segment_id IS NOT NULL\n  ),\n  effective_owner AS (\n    SELECT owner.attached\n      FROM segment_ancestry AS owned\n      JOIN console_trace_owners AS owner\n        ON owner.root_segment_id = owned.segment_id\n     ORDER BY owned.depth\n     LIMIT 1\n  )\n  SELECT 1 FROM effective_owner WHERE attached = 1\n)\nBEGIN\n  SELECT RAISE(\n    ABORT,\n    'surface replacement requires one active effective owner'\n  );\nEND",
            "CREATE TRIGGER conversation_dictionary_index_ad\nAFTER DELETE ON conversations BEGIN\n  DELETE FROM conversation_dictionary_attachments WHERE conversation_id = OLD.id;\n  DELETE FROM conversation_dictionary_unresolved  WHERE conversation_id = OLD.id;\nEND",
            "CREATE TRIGGER conversation_dictionary_index_ai\nAFTER INSERT ON conversations\nWHEN NEW.metadata LIKE '%active_dictionaries%'\nBEGIN\n  INSERT OR IGNORE INTO conversation_dictionary_attachments(conversation_id, dictionary_id)\n  SELECT NEW.id, CAST(element.value AS INTEGER)\n    FROM json_each(\n           CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n           '$.active_dictionaries'\n         ) AS element\n   WHERE json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END) = 'object'\n     AND json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                   '$.active_dictionaries') = 'array'\n     AND element.type = 'integer'\n     AND typeof(element.value) = 'integer';\n\n  INSERT OR IGNORE INTO conversation_dictionary_unresolved(conversation_id)\n  SELECT NEW.id\n   WHERE json_valid(NEW.metadata) = 0\n      OR (length(NEW.metadata) - length(replace(NEW.metadata, 'active_dictionaries', ''))) / 19 <> 1\n      OR EXISTS (\n           SELECT 1\n             FROM json_each(\n                    CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                    '$.active_dictionaries'\n                  ) AS element\n            WHERE json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                            '$.active_dictionaries') = 'array'\n              AND element.type NOT IN ('null', 'object', 'array')\n              AND NOT (element.type = 'integer' AND typeof(element.value) = 'integer')\n         );\nEND",
            "CREATE TRIGGER conversation_dictionary_index_au\nAFTER UPDATE ON conversations\nWHEN NEW.metadata IS NOT OLD.metadata OR NEW.id <> OLD.id\nBEGIN\n  DELETE FROM conversation_dictionary_attachments\n   WHERE conversation_id IN (OLD.id, NEW.id);\n  DELETE FROM conversation_dictionary_unresolved\n   WHERE conversation_id IN (OLD.id, NEW.id);\n\n  INSERT OR IGNORE INTO conversation_dictionary_attachments(conversation_id, dictionary_id)\n  SELECT NEW.id, CAST(element.value AS INTEGER)\n    FROM json_each(\n           CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n           '$.active_dictionaries'\n         ) AS element\n   WHERE NEW.metadata LIKE '%active_dictionaries%'\n     AND json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END) = 'object'\n     AND json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                   '$.active_dictionaries') = 'array'\n     AND element.type = 'integer'\n     AND typeof(element.value) = 'integer';\n\n  INSERT OR IGNORE INTO conversation_dictionary_unresolved(conversation_id)\n  SELECT NEW.id\n   WHERE NEW.metadata LIKE '%active_dictionaries%'\n     AND (json_valid(NEW.metadata) = 0\n      OR (length(NEW.metadata) - length(replace(NEW.metadata, 'active_dictionaries', ''))) / 19 <> 1\n      OR EXISTS (\n           SELECT 1\n             FROM json_each(\n                    CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                    '$.active_dictionaries'\n                  ) AS element\n            WHERE json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                            '$.active_dictionaries') = 'array'\n              AND element.type NOT IN ('null', 'object', 'array')\n              AND NOT (element.type = 'integer' AND typeof(element.value) = 'integer')\n         ));\nEND",
            "CREATE TRIGGER conversations_ad\nAFTER DELETE ON conversations BEGIN\n  INSERT INTO conversations_fts(conversations_fts,rowid,title)\n  SELECT 'delete',old.rowid,old.title\n  WHERE old.title IS NOT NULL;\nEND",
            "CREATE TRIGGER conversations_ai\nAFTER INSERT ON conversations BEGIN\n  INSERT INTO conversations_fts(rowid,title)\n  SELECT new.rowid,new.title\n  WHERE new.deleted = 0 AND new.title IS NOT NULL;\nEND",
            "CREATE TRIGGER conversations_au\nAFTER UPDATE ON conversations BEGIN\n  INSERT INTO conversations_fts(conversations_fts,rowid,title)\n  SELECT 'delete',old.rowid,old.title\n  WHERE old.deleted = 0 AND old.title IS NOT NULL;\n\n  INSERT INTO conversations_fts(rowid,title)\n  SELECT new.rowid,new.title\n  WHERE new.deleted = 0 AND new.title IS NOT NULL;\nEND",
            "CREATE TRIGGER conversations_sync_create\nAFTER INSERT ON conversations BEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('conversations',NEW.id,'create',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'root_id',NEW.root_id,'forked_from_message_id',NEW.forked_from_message_id,\n                     'parent_conversation_id',NEW.parent_conversation_id,'character_id',NEW.character_id,\n                     'assistant_kind',NEW.assistant_kind,'assistant_id',NEW.assistant_id,\n                     'persona_memory_mode',NEW.persona_memory_mode,'scope_type',NEW.scope_type,\n                     'workspace_id',NEW.workspace_id,'state',NEW.state,'topic_label',NEW.topic_label,\n                     'topic_label_source',NEW.topic_label_source,'topic_last_tagged_at',NEW.topic_last_tagged_at,\n                     'topic_last_tagged_message_id',NEW.topic_last_tagged_message_id,'cluster_id',NEW.cluster_id,\n                     'source',NEW.source,'external_ref',NEW.external_ref,\n                     'runtime_backend',NEW.runtime_backend,'discovery_owner',NEW.discovery_owner,\n                     'discovery_entity_id',NEW.discovery_entity_id,'system_prompt',NEW.system_prompt,\n                     'metadata',NEW.metadata,'thinking_history_policy',NEW.thinking_history_policy,\n                     'title',NEW.title,'rating',NEW.rating,'created_at',NEW.created_at,'last_modified',NEW.last_modified,\n                     'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER conversations_sync_delete\nAFTER UPDATE ON conversations\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('conversations',NEW.id,'delete',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'deleted',NEW.deleted,'last_modified',NEW.last_modified,\n                     'version',NEW.version,'client_id',NEW.client_id));\nEND",
            "CREATE TRIGGER conversations_sync_undelete\nAFTER UPDATE ON conversations\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('conversations',NEW.id,'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'root_id',NEW.root_id,'forked_from_message_id',NEW.forked_from_message_id,\n                     'parent_conversation_id',NEW.parent_conversation_id,'character_id',NEW.character_id,\n                     'assistant_kind',NEW.assistant_kind,'assistant_id',NEW.assistant_id,\n                     'persona_memory_mode',NEW.persona_memory_mode,'scope_type',NEW.scope_type,\n                     'workspace_id',NEW.workspace_id,'state',NEW.state,'topic_label',NEW.topic_label,\n                     'topic_label_source',NEW.topic_label_source,'topic_last_tagged_at',NEW.topic_last_tagged_at,\n                     'topic_last_tagged_message_id',NEW.topic_last_tagged_message_id,'cluster_id',NEW.cluster_id,\n                     'source',NEW.source,'external_ref',NEW.external_ref,\n                     'runtime_backend',NEW.runtime_backend,'discovery_owner',NEW.discovery_owner,\n                     'discovery_entity_id',NEW.discovery_entity_id,'system_prompt',NEW.system_prompt,\n                     'metadata',NEW.metadata,'thinking_history_policy',NEW.thinking_history_policy,\n                     'title',NEW.title,'rating',NEW.rating,'created_at',NEW.created_at,'last_modified',NEW.last_modified,\n                     'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER conversations_sync_update\nAFTER UPDATE ON conversations\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.title IS NOT NEW.title OR\n     OLD.rating IS NOT NEW.rating OR\n     OLD.forked_from_message_id IS NOT NEW.forked_from_message_id OR\n     OLD.parent_conversation_id IS NOT NEW.parent_conversation_id OR\n     OLD.character_id IS NOT NEW.character_id OR\n     OLD.assistant_kind IS NOT NEW.assistant_kind OR\n     OLD.assistant_id IS NOT NEW.assistant_id OR\n     OLD.persona_memory_mode IS NOT NEW.persona_memory_mode OR\n     OLD.scope_type IS NOT NEW.scope_type OR\n     OLD.workspace_id IS NOT NEW.workspace_id OR\n     OLD.state IS NOT NEW.state OR\n     OLD.topic_label IS NOT NEW.topic_label OR\n     OLD.topic_label_source IS NOT NEW.topic_label_source OR\n     OLD.topic_last_tagged_at IS NOT NEW.topic_last_tagged_at OR\n     OLD.topic_last_tagged_message_id IS NOT NEW.topic_last_tagged_message_id OR\n     OLD.cluster_id IS NOT NEW.cluster_id OR\n     OLD.source IS NOT NEW.source OR\n     OLD.external_ref IS NOT NEW.external_ref OR\n     OLD.runtime_backend IS NOT NEW.runtime_backend OR\n     OLD.discovery_owner IS NOT NEW.discovery_owner OR\n     OLD.discovery_entity_id IS NOT NEW.discovery_entity_id OR\n     OLD.system_prompt IS NOT NEW.system_prompt OR\n     OLD.metadata IS NOT NEW.metadata OR\n     OLD.thinking_history_policy IS NOT NEW.thinking_history_policy OR\n     OLD.root_id IS NOT NEW.root_id OR\n     OLD.created_at IS NOT NEW.created_at OR\n     OLD.client_id IS NOT NEW.client_id OR\n     (OLD.archived IS NEW.archived AND (\n         OLD.last_modified IS NOT NEW.last_modified OR\n         OLD.version IS NOT NEW.version)))\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('conversations',NEW.id,'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'root_id',NEW.root_id,'forked_from_message_id',NEW.forked_from_message_id,\n                     'parent_conversation_id',NEW.parent_conversation_id,'character_id',NEW.character_id,\n                     'assistant_kind',NEW.assistant_kind,'assistant_id',NEW.assistant_id,\n                     'persona_memory_mode',NEW.persona_memory_mode,'scope_type',NEW.scope_type,\n                     'workspace_id',NEW.workspace_id,'state',NEW.state,'topic_label',NEW.topic_label,\n                     'topic_label_source',NEW.topic_label_source,'topic_last_tagged_at',NEW.topic_last_tagged_at,\n                     'topic_last_tagged_message_id',NEW.topic_last_tagged_message_id,'cluster_id',NEW.cluster_id,\n                     'source',NEW.source,'external_ref',NEW.external_ref,\n                     'runtime_backend',NEW.runtime_backend,'discovery_owner',NEW.discovery_owner,\n                     'discovery_entity_id',NEW.discovery_entity_id,'system_prompt',NEW.system_prompt,\n                     'metadata',NEW.metadata,'thinking_history_policy',NEW.thinking_history_policy,\n                     'title',NEW.title,'rating',NEW.rating,'created_at',NEW.created_at,'last_modified',NEW.last_modified,\n                     'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER flashcards_ad AFTER DELETE ON flashcards BEGIN\n    INSERT INTO flashcards_fts(flashcards_fts, rowid, front, back, tags)\n    VALUES('delete', old.rowid, old.front, old.back, old.tags);\nEND",
            "CREATE TRIGGER flashcards_ai AFTER INSERT ON flashcards BEGIN\n    INSERT INTO flashcards_fts(rowid, front, back, tags) \n    VALUES (new.rowid, new.front, new.back, new.tags);\nEND",
            "CREATE TRIGGER flashcards_au AFTER UPDATE ON flashcards BEGIN\n    INSERT INTO flashcards_fts(flashcards_fts, rowid, front, back, tags)\n    VALUES('delete', old.rowid, old.front, old.back, old.tags);\n    INSERT INTO flashcards_fts(rowid, front, back, tags)\n    VALUES (new.rowid, new.front, new.back, new.tags);\nEND",
            "CREATE TRIGGER keyword_collections_ad\nAFTER DELETE ON keyword_collections BEGIN\n  INSERT INTO keyword_collections_fts(keyword_collections_fts,rowid,name)\n  VALUES('delete',old.id,old.name);\nEND",
            "CREATE TRIGGER keyword_collections_ai\nAFTER INSERT ON keyword_collections BEGIN\n  INSERT INTO keyword_collections_fts(rowid,name)\n  SELECT new.id,new.name\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER keyword_collections_au\nAFTER UPDATE ON keyword_collections BEGIN\n  INSERT INTO keyword_collections_fts(keyword_collections_fts,rowid,name)\n  SELECT 'delete',old.id,old.name\n  WHERE old.deleted = 0;\n\n  INSERT INTO keyword_collections_fts(rowid,name)\n  SELECT new.id,new.name\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER keyword_collections_sync_create\nAFTER INSERT ON keyword_collections BEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('keyword_collections',CAST(NEW.id AS TEXT),'create',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'name',NEW.name,'parent_id',NEW.parent_id,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER keyword_collections_sync_delete\nAFTER UPDATE ON keyword_collections\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('keyword_collections',CAST(NEW.id AS TEXT),'delete',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'deleted',NEW.deleted,'last_modified',NEW.last_modified,\n                     'version',NEW.version,'client_id',NEW.client_id));\nEND",
            "CREATE TRIGGER keyword_collections_sync_undelete\nAFTER UPDATE ON keyword_collections\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('keyword_collections',CAST(NEW.id AS TEXT),'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'name',NEW.name,'parent_id',NEW.parent_id,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER keyword_collections_sync_update\nAFTER UPDATE ON keyword_collections\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.name IS NOT NEW.name OR\n     OLD.parent_id IS NOT NEW.parent_id OR\n     OLD.last_modified IS NOT NEW.last_modified OR\n     OLD.version IS NOT NEW.version)\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('keyword_collections',CAST(NEW.id AS TEXT),'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'name',NEW.name,'parent_id',NEW.parent_id,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER keywords_ai\nAFTER INSERT ON keywords BEGIN\n  INSERT INTO keywords_fts(rowid, keyword)\n  SELECT new.id, new.keyword\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER keywords_au\nAFTER UPDATE ON keywords BEGIN\n  /* delete the old doc only if it was indexed */\n  INSERT INTO keywords_fts(keywords_fts, rowid, keyword)\n  SELECT 'delete', old.id, old.keyword\n  WHERE old.deleted = 0;\n\n  /* add the new doc if it should be indexed */\n  INSERT INTO keywords_fts(rowid, keyword)\n  SELECT new.id, new.keyword\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER keywords_bd\nBEFORE DELETE ON keywords BEGIN\n  INSERT INTO keywords_fts(keywords_fts, rowid, keyword)\n  SELECT 'delete', old.id, old.keyword\n  WHERE old.deleted = 0;\nEND",
            "CREATE TRIGGER keywords_sync_create\nAFTER INSERT ON keywords BEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('keywords',CAST(NEW.id AS TEXT),'create',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'keyword',NEW.keyword,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER keywords_sync_delete\nAFTER UPDATE ON keywords\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('keywords',CAST(NEW.id AS TEXT),'delete',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'deleted',NEW.deleted,'last_modified',NEW.last_modified,\n                     'version',NEW.version,'client_id',NEW.client_id));\nEND",
            "CREATE TRIGGER keywords_sync_undelete\nAFTER UPDATE ON keywords\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('keywords',CAST(NEW.id AS TEXT),'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'keyword',NEW.keyword,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER keywords_sync_update\nAFTER UPDATE ON keywords\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.keyword IS NOT NEW.keyword OR -- Though keyword itself is unlikely to change if it's the unique identifier\n     OLD.last_modified IS NOT NEW.last_modified OR\n     OLD.version IS NOT NEW.version)\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('keywords',CAST(NEW.id AS TEXT),'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'keyword',NEW.keyword,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER message_attachments_semantic_delete_guard\nBEFORE DELETE ON message_attachments\nWHEN EXISTS (\n  SELECT 1\n    FROM console_trace_semantic_revisions AS revision\n   WHERE revision.live_message_id = OLD.message_id\n) AND console_semantic_mutation_authorized(OLD.message_id, 'attachment_delete') <> 1\nBEGIN\n  SELECT RAISE(ABORT, 'semantic mutation authorization required for attachment delete');\nEND",
            "CREATE TRIGGER message_attachments_semantic_insert_guard\nBEFORE INSERT ON message_attachments\nWHEN EXISTS (\n  SELECT 1\n    FROM console_trace_semantic_revisions AS revision\n   WHERE revision.live_message_id = NEW.message_id\n) AND console_semantic_mutation_authorized(NEW.message_id, 'attachment_insert') <> 1\nBEGIN\n  SELECT RAISE(ABORT, 'semantic mutation authorization required for attachment insert');\nEND",
            "CREATE TRIGGER message_attachments_semantic_update_guard\nBEFORE UPDATE ON message_attachments\nWHEN (\n  EXISTS (\n    SELECT 1\n      FROM console_trace_semantic_revisions AS revision\n     WHERE revision.live_message_id = OLD.message_id\n  ) OR EXISTS (\n    SELECT 1\n      FROM console_trace_semantic_revisions AS revision\n     WHERE revision.live_message_id = NEW.message_id\n  )\n) AND (\n  console_semantic_mutation_authorized(OLD.message_id, 'attachment_update') <> 1 OR\n  OLD.message_id IS NOT NEW.message_id\n)\nBEGIN\n  SELECT RAISE(ABORT, 'semantic mutation authorization required for attachment update');\nEND",
            "CREATE TRIGGER messages_ad\nAFTER DELETE ON messages BEGIN\n  INSERT INTO messages_fts(messages_fts,rowid,content)\n  SELECT 'delete',old.rowid,old.content\n  WHERE EXISTS (SELECT 1 FROM messages_fts_docsize WHERE rowid = old.rowid);\nEND",
            "CREATE TRIGGER messages_ai\nAFTER INSERT ON messages BEGIN\n  INSERT INTO messages_fts(rowid,content)\n  SELECT new.rowid,new.content\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER messages_au\nAFTER UPDATE OF content, deleted ON messages BEGIN\n  INSERT INTO messages_fts(messages_fts,rowid,content)\n  SELECT 'delete',old.rowid,old.content\n  WHERE old.deleted = 0\n    AND EXISTS (SELECT 1 FROM messages_fts_docsize WHERE rowid = old.rowid);\n\n  INSERT INTO messages_fts(rowid,content)\n  SELECT new.rowid,new.content\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER messages_semantic_delete_guard\nBEFORE DELETE ON messages\nWHEN EXISTS (\n  SELECT 1\n    FROM console_trace_semantic_revisions AS revision\n   WHERE revision.live_message_id = OLD.id\n) AND console_semantic_mutation_authorized(OLD.id, 'message_delete') <> 1\nBEGIN\n  SELECT RAISE(ABORT, 'semantic mutation authorization required for message delete');\nEND",
            "CREATE TRIGGER messages_semantic_update_guard\nBEFORE UPDATE OF\n  id, conversation_id, parent_message_id, sender, role, content, image_data,\n  image_mime_type, provider_continuation_json, thinking_blocks_json,\n  assistant_generation_state\nON messages\nWHEN EXISTS (\n  SELECT 1\n    FROM console_trace_semantic_revisions AS revision\n   WHERE revision.live_message_id = OLD.id\n) AND (\n  OLD.id IS NOT NEW.id OR\n  OLD.conversation_id IS NOT NEW.conversation_id OR\n  OLD.parent_message_id IS NOT NEW.parent_message_id OR\n  OLD.sender IS NOT NEW.sender OR\n  OLD.role IS NOT NEW.role OR\n  OLD.content IS NOT NEW.content OR\n  OLD.image_data IS NOT NEW.image_data OR\n  OLD.image_mime_type IS NOT NEW.image_mime_type OR\n  OLD.provider_continuation_json IS NOT NEW.provider_continuation_json OR\n  OLD.thinking_blocks_json IS NOT NEW.thinking_blocks_json OR\n  OLD.assistant_generation_state IS NOT NEW.assistant_generation_state\n) AND console_semantic_mutation_authorized(OLD.id, 'message_update') <> 1\nBEGIN\n  SELECT RAISE(ABORT, 'semantic mutation authorization required for message update');\nEND",
            "CREATE TRIGGER messages_sync_create\nAFTER INSERT ON messages BEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('messages',NEW.id,'create',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'conversation_id',NEW.conversation_id,'parent_message_id',NEW.parent_message_id,\n                     'sender',NEW.sender,'content',NEW.content,\n                     'image_mime_type',NEW.image_mime_type,\n                     'provider_continuation_json',NEW.provider_continuation_json,\n                     'thinking_blocks_json',NEW.thinking_blocks_json,\n                     'assistant_generation_state',NEW.assistant_generation_state,\n                     'timestamp',NEW.timestamp,'ranking',NEW.ranking,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER messages_sync_delete\nAFTER UPDATE ON messages\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('messages',NEW.id,'delete',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'deleted',NEW.deleted,'last_modified',NEW.last_modified,\n                     'assistant_generation_state',NEW.assistant_generation_state,\n                     'version',NEW.version,'client_id',NEW.client_id));\nEND",
            "CREATE TRIGGER messages_sync_undelete\nAFTER UPDATE ON messages\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('messages',NEW.id,'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'conversation_id',NEW.conversation_id,'parent_message_id',NEW.parent_message_id,\n                     'sender',NEW.sender,'content',NEW.content,\n                     'image_mime_type',NEW.image_mime_type,\n                     'provider_continuation_json',NEW.provider_continuation_json,\n                     'thinking_blocks_json',NEW.thinking_blocks_json,\n                     'assistant_generation_state',NEW.assistant_generation_state,\n                     'timestamp',NEW.timestamp,'ranking',NEW.ranking,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER messages_sync_update\nAFTER UPDATE ON messages\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.content IS NOT NEW.content OR\n     OLD.image_data IS NOT NEW.image_data OR\n     OLD.image_mime_type IS NOT NEW.image_mime_type OR\n     OLD.provider_continuation_json IS NOT NEW.provider_continuation_json OR\n     OLD.thinking_blocks_json IS NOT NEW.thinking_blocks_json OR\n     OLD.assistant_generation_state IS NOT NEW.assistant_generation_state OR\n     OLD.ranking IS NOT NEW.ranking OR\n     OLD.parent_message_id IS NOT NEW.parent_message_id OR\n     OLD.last_modified IS NOT NEW.last_modified OR\n     OLD.version IS NOT NEW.version)\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('messages',NEW.id,'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'conversation_id',NEW.conversation_id,'parent_message_id',NEW.parent_message_id,\n                     'sender',NEW.sender,'content',NEW.content,\n                     'image_mime_type',NEW.image_mime_type,\n                     'provider_continuation_json',NEW.provider_continuation_json,\n                     'thinking_blocks_json',NEW.thinking_blocks_json,\n                     'assistant_generation_state',NEW.assistant_generation_state,\n                     'timestamp',NEW.timestamp,'ranking',NEW.ranking,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER mindmap_nodes_ad AFTER DELETE ON mindmap_nodes BEGIN\n    DELETE FROM mindmap_nodes_fts WHERE rowid = old.rowid;\nEND",
            "CREATE TRIGGER mindmap_nodes_ai AFTER INSERT ON mindmap_nodes BEGIN\n    INSERT INTO mindmap_nodes_fts(rowid, text) \n    VALUES (new.rowid, new.text);\nEND",
            "CREATE TRIGGER mindmap_nodes_au AFTER UPDATE ON mindmap_nodes BEGIN\n    DELETE FROM mindmap_nodes_fts WHERE rowid = old.rowid;\n    INSERT INTO mindmap_nodes_fts(rowid, text) \n    VALUES (new.rowid, new.text);\nEND",
            "CREATE TRIGGER notes_ad\nAFTER DELETE ON notes BEGIN\n  INSERT INTO notes_fts(notes_fts,rowid,title,content)\n  VALUES('delete',old.rowid,old.title,old.content);\nEND",
            "CREATE TRIGGER notes_ai\nAFTER INSERT ON notes BEGIN\n  INSERT INTO notes_fts(rowid,title,content)\n  SELECT new.rowid,new.title,new.content\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER notes_au\nAFTER UPDATE ON notes BEGIN\n  INSERT INTO notes_fts(notes_fts,rowid,title,content)\n  SELECT 'delete',old.rowid,old.title,old.content\n  WHERE old.deleted = 0;\n\n  INSERT INTO notes_fts(rowid,title,content)\n  SELECT new.rowid,new.title,new.content\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER notes_sync_create\nAFTER INSERT ON notes BEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('notes',NEW.id,'create',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'title',NEW.title,'content',NEW.content,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER notes_sync_delete\nAFTER UPDATE ON notes\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('notes',NEW.id,'delete',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'deleted',NEW.deleted,'last_modified',NEW.last_modified,\n                     'version',NEW.version,'client_id',NEW.client_id));\nEND",
            "CREATE TRIGGER notes_sync_undelete\nAFTER UPDATE ON notes\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('notes',NEW.id,'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'title',NEW.title,'content',NEW.content,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER notes_sync_update\nAFTER UPDATE ON notes\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.title IS NOT NEW.title OR\n     OLD.content IS NOT NEW.content OR\n     OLD.last_modified IS NOT NEW.last_modified OR\n     OLD.version IS NOT NEW.version)\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('notes',NEW.id,'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'title',NEW.title,'content',NEW.content,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER sync_log_prune_character_cards\nAFTER UPDATE ON character_cards\nWHEN NEW.version > 1\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'character_cards'\n     AND entity_id = CAST(NEW.id AS TEXT)\n     AND version < NEW.version;\nEND",
            "CREATE TRIGGER sync_log_prune_character_cards_hard\nAFTER DELETE ON character_cards\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'character_cards' AND entity_id = CAST(OLD.id AS TEXT);\nEND",
            "CREATE TRIGGER sync_log_prune_chat_dictionaries\nAFTER INSERT ON sync_log\nWHEN NEW.entity = 'chat_dictionaries'\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'chat_dictionaries'\n     AND entity_id = NEW.entity_id\n     AND (version < NEW.version\n          OR (operation <> 'delete'\n              AND (change_id < NEW.change_id\n                   OR NOT EXISTS (SELECT 1 FROM chat_dictionaries AS src\n                                   WHERE CAST(src.id AS TEXT) = NEW.entity_id\n                                     AND src.deleted = 0))));\nEND",
            "CREATE TRIGGER sync_log_prune_chat_dictionaries_hard\nAFTER DELETE ON chat_dictionaries\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'chat_dictionaries' AND entity_id = CAST(OLD.id AS TEXT);\nEND",
            "CREATE TRIGGER sync_log_prune_conversations\nAFTER INSERT ON sync_log\nWHEN NEW.entity = 'conversations'\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'conversations'\n     AND entity_id = NEW.entity_id\n     AND version < (\n         SELECT MAX(frontier.version) FROM sync_log AS frontier\n          WHERE frontier.entity = 'conversations'\n            AND frontier.entity_id = NEW.entity_id);\nEND",
            "CREATE TRIGGER sync_log_prune_conversations_hard\nAFTER DELETE ON conversations\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'conversations' AND entity_id = OLD.id;\nEND",
            "CREATE TRIGGER sync_log_prune_keyword_collections\nAFTER UPDATE ON keyword_collections\nWHEN NEW.version > 1\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'keyword_collections'\n     AND entity_id = CAST(NEW.id AS TEXT)\n     AND version < NEW.version;\nEND",
            "CREATE TRIGGER sync_log_prune_keyword_collections_hard\nAFTER DELETE ON keyword_collections\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'keyword_collections' AND entity_id = CAST(OLD.id AS TEXT);\nEND",
            "CREATE TRIGGER sync_log_prune_keywords\nAFTER UPDATE ON keywords\nWHEN NEW.version > 1\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'keywords'\n     AND entity_id = CAST(NEW.id AS TEXT)\n     AND version < NEW.version;\nEND",
            "CREATE TRIGGER sync_log_prune_keywords_hard\nAFTER DELETE ON keywords\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'keywords' AND entity_id = CAST(OLD.id AS TEXT);\nEND",
            "CREATE TRIGGER sync_log_prune_messages\nAFTER UPDATE ON messages\nWHEN NEW.version > 1\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'messages'\n     AND entity_id = NEW.id\n     AND version < (CASE WHEN NEW.deleted = 1\n                         THEN NEW.version\n                         ELSE NEW.version - 1 END);\nEND",
            "CREATE TRIGGER sync_log_prune_messages_hard\nAFTER DELETE ON messages\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'messages' AND entity_id = OLD.id;\nEND",
            "CREATE TRIGGER sync_log_prune_notes\nAFTER UPDATE ON notes\nWHEN NEW.version > 1\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'notes'\n     AND entity_id = NEW.id\n     AND version < NEW.version;\nEND",
            "CREATE TRIGGER sync_log_prune_notes_hard\nAFTER DELETE ON notes\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'notes' AND entity_id = OLD.id;\nEND",
            "CREATE TRIGGER sync_log_prune_world_book_entries\nAFTER INSERT ON sync_log\nWHEN NEW.entity = 'world_book_entries'\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'world_book_entries'\n     AND entity_id = NEW.entity_id\n     AND operation <> 'delete'\n     AND (change_id < NEW.change_id\n          OR NOT EXISTS (SELECT 1 FROM world_book_entries AS src\n                          WHERE CAST(src.id AS TEXT) = NEW.entity_id));\nEND",
            "CREATE TRIGGER sync_log_prune_world_book_entries_hard\nAFTER DELETE ON world_book_entries\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'world_book_entries'\n     AND entity_id = CAST(OLD.id AS TEXT)\n     AND operation <> 'delete';\nEND",
            "CREATE TRIGGER sync_log_prune_world_books\nAFTER INSERT ON sync_log\nWHEN NEW.entity = 'world_books'\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'world_books'\n     AND entity_id = NEW.entity_id\n     AND (version < NEW.version\n          OR (operation <> 'delete'\n              AND (change_id < NEW.change_id\n                   OR NOT EXISTS (SELECT 1 FROM world_books AS src\n                                   WHERE CAST(src.id AS TEXT) = NEW.entity_id\n                                     AND src.deleted = 0))));\nEND",
            "CREATE TRIGGER sync_log_prune_world_books_hard\nAFTER DELETE ON world_books\nBEGIN\n  DELETE FROM sync_log\n   WHERE entity = 'world_books' AND entity_id = CAST(OLD.id AS TEXT);\nEND",
            "CREATE TRIGGER topics_ad AFTER DELETE ON topics BEGIN\n    DELETE FROM topics_fts WHERE rowid = old.rowid;\nEND",
            "CREATE TRIGGER topics_ai AFTER INSERT ON topics BEGIN\n    INSERT INTO topics_fts(rowid, title, content) \n    VALUES (new.rowid, new.title, new.content);\nEND",
            "CREATE TRIGGER topics_au AFTER UPDATE ON topics BEGIN\n    DELETE FROM topics_fts WHERE rowid = old.rowid;\n    INSERT INTO topics_fts(rowid, title, content) \n    VALUES (new.rowid, new.title, new.content);\nEND",
            "CREATE TRIGGER world_book_entries_ad\nAFTER DELETE ON world_book_entries BEGIN\n  DELETE FROM world_book_entries_fts WHERE rowid = OLD.id;\nEND",
            "CREATE TRIGGER world_book_entries_ai\nAFTER INSERT ON world_book_entries BEGIN\n  INSERT INTO world_book_entries_fts(rowid, keys, content)\n  VALUES(NEW.id, NEW.keys, NEW.content);\nEND",
            "CREATE TRIGGER world_book_entries_au\nAFTER UPDATE ON world_book_entries BEGIN\n  INSERT INTO world_book_entries_fts(world_book_entries_fts, rowid, keys, content)\n  VALUES('delete', OLD.id, OLD.keys, OLD.content);\n  \n  INSERT INTO world_book_entries_fts(rowid, keys, content)\n  VALUES(NEW.id, NEW.keys, NEW.content);\nEND",
            "CREATE TRIGGER world_book_entries_sync_create\nAFTER INSERT ON world_book_entries BEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('world_book_entries', CAST(NEW.id AS TEXT), 'create', NEW.last_modified,\n         (SELECT client_id FROM world_books WHERE id = NEW.world_book_id), 1,\n         json_object('id', NEW.id, 'world_book_id', NEW.world_book_id, 'keys', NEW.keys,\n                     'content', NEW.content, 'enabled', NEW.enabled, 'position', NEW.position,\n                     'insertion_order', NEW.insertion_order, 'priority', NEW.priority,\n                     'selective', NEW.selective, 'secondary_keys', NEW.secondary_keys,\n                     'case_sensitive', NEW.case_sensitive, 'regex', NEW.regex,\n                     'extensions', NEW.extensions,\n                     'created_at', NEW.created_at, 'last_modified', NEW.last_modified));\nEND",
            "CREATE TRIGGER world_book_entries_sync_delete\nAFTER DELETE ON world_book_entries BEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('world_book_entries', CAST(OLD.id AS TEXT), 'delete', datetime('now'),\n         (SELECT client_id FROM world_books WHERE id = OLD.world_book_id), 1,\n         json_object('id', OLD.id, 'world_book_id', OLD.world_book_id));\nEND",
            "CREATE TRIGGER world_book_entries_sync_update\nAFTER UPDATE ON world_book_entries\nWHEN OLD.keys IS NOT NEW.keys OR\n     OLD.content IS NOT NEW.content OR\n     OLD.enabled IS NOT NEW.enabled OR\n     OLD.position IS NOT NEW.position OR\n     OLD.insertion_order IS NOT NEW.insertion_order OR\n     OLD.priority IS NOT NEW.priority OR\n     OLD.selective IS NOT NEW.selective OR\n     OLD.secondary_keys IS NOT NEW.secondary_keys OR\n     OLD.case_sensitive IS NOT NEW.case_sensitive OR\n     OLD.regex IS NOT NEW.regex OR\n     OLD.extensions IS NOT NEW.extensions\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('world_book_entries', CAST(NEW.id AS TEXT), 'update', NEW.last_modified,\n         (SELECT client_id FROM world_books WHERE id = NEW.world_book_id), 1,\n         json_object('id', NEW.id, 'world_book_id', NEW.world_book_id, 'keys', NEW.keys,\n                     'content', NEW.content, 'enabled', NEW.enabled, 'position', NEW.position,\n                     'insertion_order', NEW.insertion_order, 'priority', NEW.priority,\n                     'selective', NEW.selective, 'secondary_keys', NEW.secondary_keys,\n                     'case_sensitive', NEW.case_sensitive, 'regex', NEW.regex,\n                     'extensions', NEW.extensions,\n                     'created_at', NEW.created_at, 'last_modified', NEW.last_modified));\nEND",
            "CREATE TRIGGER world_books_ad\nAFTER DELETE ON world_books BEGIN\n  DELETE FROM world_books_fts WHERE rowid = OLD.id;\nEND",
            "CREATE TRIGGER world_books_ai\nAFTER INSERT ON world_books BEGIN\n  INSERT INTO world_books_fts(rowid, name, description)\n  VALUES(NEW.id, NEW.name, NEW.description);\nEND",
            "CREATE TRIGGER world_books_au\nAFTER UPDATE ON world_books BEGIN\n  INSERT INTO world_books_fts(world_books_fts, rowid, name, description)\n  SELECT 'delete', OLD.id, OLD.name, OLD.description\n  WHERE OLD.deleted = 0;\n\n  INSERT INTO world_books_fts(rowid, name, description)\n  SELECT NEW.id, NEW.name, NEW.description\n  WHERE NEW.deleted = 0;\nEND",
            "CREATE TRIGGER world_books_sync_create\nAFTER INSERT ON world_books BEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('world_books', CAST(NEW.id AS TEXT), 'create', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'scan_depth', NEW.scan_depth, 'token_budget', NEW.token_budget,\n                     'recursive_scanning', NEW.recursive_scanning, 'enabled', NEW.enabled,\n                     'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
            "CREATE TRIGGER world_books_sync_delete\nAFTER UPDATE ON world_books\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('world_books', CAST(NEW.id AS TEXT), 'delete', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'deleted', NEW.deleted, 'last_modified', NEW.last_modified,\n                     'version', NEW.version, 'client_id', NEW.client_id));\nEND",
            "CREATE TRIGGER world_books_sync_undelete\nAFTER UPDATE ON world_books\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('world_books', CAST(NEW.id AS TEXT), 'update', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'scan_depth', NEW.scan_depth, 'token_budget', NEW.token_budget,\n                     'recursive_scanning', NEW.recursive_scanning, 'enabled', NEW.enabled,\n                     'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
            "CREATE TRIGGER world_books_sync_update\nAFTER UPDATE ON world_books\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.name IS NOT NEW.name OR\n     OLD.description IS NOT NEW.description OR\n     OLD.scan_depth IS NOT NEW.scan_depth OR\n     OLD.token_budget IS NOT NEW.token_budget OR\n     OLD.recursive_scanning IS NOT NEW.recursive_scanning OR\n     OLD.enabled IS NOT NEW.enabled OR\n     OLD.last_modified IS NOT NEW.last_modified OR\n     OLD.version IS NOT NEW.version)\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('world_books', CAST(NEW.id AS TEXT), 'update', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'scan_depth', NEW.scan_depth, 'token_budget', NEW.token_budget,\n                     'recursive_scanning', NEW.recursive_scanning, 'enabled', NEW.enabled,\n                     'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
